(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-066"]={"sura":66,"name_ar":"التحريم","name_en":"At-Tahrim","verses":12,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":12,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=66&ayah=5\" class=\"link\">66:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 66:5 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=66&ayah=5\" class=\"link\">66:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 66:5 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=66&ayah=5\" class=\"link\">66:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 66:5 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=66&ayah=5\" class=\"link\">66:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 66:5 ஐ பார்க்கவும்"},"5":{"html":"<strong>மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<p><span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span></p><br />\r\n<br />\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.)<br />\r\n<br />\r\n<strong>வேதம் அவருக்கு அனுமதித்த ஒரு காரியத்தை நபி (ஸல்) அவர்கள் தமக்குத் தாமே தடுத்துக் கொண்டதற்காக அல்லாஹ் அவர்களைக் கண்டிக்கிறான்</strong><br />\r\n<br />\r\nஅல்-புகாரி (ரஹ்) பதிவு செய்துள்ளார்கள்: உபைத் பின் உமைர் அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஜைனப் பின்த் ஜஹ்ஷ் (ரழி) அவர்களின் இல்லத்தில் சிறிது நேரம் தங்கி, அங்கு தேன் அருந்துவது வழக்கம் என்று ஆயிஷா (ரழி) அவர்கள் கூறியதாக நான் கேள்விப்பட்டேன். (ஆயிஷா (ரழி) மேலும் கூறினார்கள்:) \"நபி (ஸல்) அவர்கள் எங்களில் யாரிடம் நுழைந்தாலும், 'உங்களிடமிருந்து மஃகாஃபீரின் வாடை வீசுகிறதே, நீங்கள் மஃகாஃபீர் (ஒரு வகை பிசின்) சாப்பிட்டீர்களா?' என்று கேட்க நானும் ஹஃப்ஸா (ரழி) அவர்களும் முடிவு செய்தோம். நபி (ஸல்) அவர்கள் எங்களில் ஒருவரிடம் வந்தபோது, அவர் அவ்வாறே கேட்டார். அதற்கு நபி (ஸல்) அவர்கள்,\"<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">شَرِبْتُ</span> <span class=\"quran-arabic-font text-success\">عَسَلًا</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">زَيْنَبَ</span> <span class=\"quran-arabic-font text-success\">بِنْتِ</span> <span class=\"quran-arabic-font text-success\">جَحْشٍ</span> <span class=\"quran-arabic-font text-success\">وَلَنْ</span> <span class=\"quran-arabic-font text-success\">أَعُودَ</span> <span class=\"quran-arabic-font text-success\">لَه</span>»<br />\r\n<br />\r\n(இல்லை, நான் ஜைனப் பின்த் ஜஹ்ஷ் (ரழி) அவர்களின் வீட்டில் தேன் அருந்தினேன். இனி நான் அதை அருந்தவே மாட்டேன்) என்று பதிலளித்தார்கள். அதன் பிறகு பின்வரும் வசனங்கள் அருளப்பட்டன:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّبِىُّ</span> <span class=\"quran-arabic-font text-success\">لِمَ</span> <span class=\"quran-arabic-font text-success\">تُحَرِّمُ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَحَلَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span><br />\r\n<br />\r\n(நபியே! அல்லாஹ் உமக்கு அனுமதித்ததை நீர் ஏன் தடுத்துக் கொள்கிறீர்) என்பது முதல்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَتُوبَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">صَغَتْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبُكُمَا</span><br />\r\n<br />\r\n(நீங்கள் இருவரும் அல்லாஹ்விடம் பாவமன்னிப்புத் தேடினால் (அது உங்களுக்கு நலம்); ஏனெனில் உங்கள் இருவருடைய உள்ளங்களும் (சத்தியத்திலிருந்து) நிச்சயமாகச் சாய்ந்துவிட்டன) என்பது வரை. இது ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) ஆகியோரைக் குறிப்பிடுகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَ</span> <span class=\"quran-arabic-font text-success\">أَسَرَّ</span> <span class=\"quran-arabic-font text-success\">النَّبِىُّ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضِ</span> <span class=\"quran-arabic-font text-success\">أَزْوَجِهِ</span> <span class=\"quran-arabic-font text-success\">حَدِيثاً</span><br />\r\n<br />\r\n(நபி தம் மனைவியரில் ஒருவரிடம் ஒரு செய்தியை இரகசியமாகக் கூறியபோது (நினைவுகூருங்கள்)) - இது நபி (ஸல்) அவர்களின் இந்தக் கூற்றைக் குறிக்கிறது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">شَرِبْتُ</span> <span class=\"quran-arabic-font text-success\">عَسَلًا</span>»<br />\r\n<br />\r\n(நான் தேன் அருந்தினேன்.) இப்ராஹீம் பின் மூஸா, ஹிஷாம் வழியாகக் கூறும்போது, இது நபி (ஸல்) அவர்களின் இந்தக் கூற்றையும் குறிக்கும் என்று கூறுகிறார்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَلَنْ</span> <span class=\"quran-arabic-font text-success\">أَعُودَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">حَلَفْتُ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">تُخْبِرِي</span> <span class=\"quran-arabic-font text-success\">بِذَلِكِ</span> <span class=\"quran-arabic-font text-success\">أَحَدًا</span>»<br />\r\n<br />\r\n(இனிமேல் நான் அதை அருந்த மாட்டேன், இதற்காக நான் சத்தியம் செய்துள்ளேன். எனவே, இதை யாரிடமும் சொல்ல வேண்டாம்.) அல்-புகாரி (ரஹ்) இந்த ஹதீஸை விவாகரத்து (தலாக்) அத்தியாயத்திலும் பதிவு செய்துள்ளார்கள். பிறகு அவர், \"மஃகாஃபீர் என்பது மரத்திலிருந்து வடியும் ஒரு வகை பிசின்; 'அர்-ரிம்த்' எனும் செடியில் அதன் சுவை இனிப்பாக இருக்கும்...\" என்று கூறுகிறார். அல்-ஜவ்ஹரி கூறுகிறார்: \"உர்ஃபுத் என்பது ஒரு வகை புதர்ச் செடி, அது மக்ஃபூரைச் சுரக்கும்.\" இமாம் முஸ்லிம் (ரஹ்) இந்த ஹதீஸை ஆயிஷா (ரழி) அவர்களின் அறிவிப்பாகத் தனது ஸஹீஹில் விவாகரத்து அத்தியாயத்தில் பதிவு செய்துள்ளார். அதன் வாசகம், புகாரியின் நேர்ச்சைகள் அத்தியாயத்தில் உள்ள வாசகத்தைப் போன்றதே. விவாகரத்து அத்தியாயத்தில் அல்-புகாரி (ரஹ்) பதிவு செய்துள்ள மற்றோர் அறிவிப்பில் ஆயிஷா (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு இனிப்புகளும் தேனும் மிகவும் பிடிக்கும். அஸர் தொழுகைக்குப் பிறகு அவர்கள் தம் மனைவியரைச் சந்தித்து, அவர்களுடன் நெருக்கமாக இருப்பது வழக்கம். ஒருமுறை ஹஃப்ஸா (ரழி) அவர்களின் அறைக்குச் சென்று, வழக்கத்தை விட அதிக நேரம் தங்கினார்கள். நான் (ஆயிஷா (ரழி)) பொறாமைப்பட்டு அதைப் பற்றி விசாரித்தேன். 'அவருடைய குடும்பத்தைச் சேர்ந்த ஒரு பெண் அவருக்கு ஒரு சிறிய பாத்திரத்தில் தேனைப் பரிசாக அனுப்பியுள்ளார், அதிலிருந்து அவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்குப் பானம் தயாரித்துக் கொடுத்தார்' என்று எனக்குத் தெரிவிக்கப்பட்டது. நான் சொன்னேன்: 'அல்லாஹ்வின் மீது ஆணையாக! நாம் அவருக்கு எதிராக ஒரு தந்திரம் செய்வோம்.' பிறகு நான் ஸவ்தா பின்த் ஜம்ஆ (ரழி) அவர்களிடம் சொன்னேன்: 'நபி (ஸல்) அவர்கள் உங்களிடம் வந்து நெருங்கும்போது, 'நீங்கள் மஃகாஃபீர் சாப்பிட்டீர்களா?' என்று கேளுங்கள். அவர் 'இல்லை' என்று கூறும்போது, 'அப்படியானால் இந்த வாடை என்ன?' என்று கேளுங்கள். அவர் 'ஹஃப்ஸா எனக்குத் தேன் குடிக்கக் கொடுத்தார்' என்று கூறுவார். அப்போது நீங்கள், 'தேனீக்கள் உர்ஃபுத் செடியிலிருந்து உண்டிருக்கலாம்' என்று சொல்லுங்கள். நானும் அவரிடம் அதையே சொல்வேன். ஸஃபிய்யா (ரழி), நீங்களும் இதையே சொல்லுங்கள்.' ஸவ்தா (ரழி) பின்னர் கூறினார்கள்: 'அல்லாஹ்வின் மீது ஆணையாக! நீங்கள் சொன்னதைச் சொல்வதற்கு நான் தயங்கினேன்; ஆனால் அதற்குள்ளாகவே நபி (ஸல்) அவர்கள் என் வாசலில் வந்து நின்றார்கள்.' அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரிடம் நெருங்கியபோது, 'அல்லாஹ்வின் தூதரே! நீங்கள் மஃகாஃபீர் சாப்பிட்டீர்களா?' என்று அவர் கேட்டார். அவர் 'இல்லை' என்றார்கள். 'அப்படியானால் இந்த வாடை என்ன?' என்று அவர் மீண்டும் கேட்டார். அதற்கு நபி (ஸல்) அவர்கள்,\"<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">سَقَتْنِي</span> <span class=\"quran-arabic-font text-success\">حَفْصَةُ</span> <span class=\"quran-arabic-font text-success\">شَرْبَةَ</span> <span class=\"quran-arabic-font text-success\">عَسَل</span>»<br />\r\n<br />\r\n(ஹஃப்ஸா எனக்குத் தேன் குடிக்கக் கொடுத்தார்) என்றார்கள். அதற்கு ஸவ்தா (ரழி), 'தேனீக்கள் உர்ஃபுத் செடியிலிருந்து உண்டிருக்கலாம்' என்றார்.\" ஆயிஷா (ரழி) அவர்கள் தொடர்ந்தார்கள்: \"நபி (ஸல்) அவர்கள் என்னிடம் வந்தபோது நானும் அவரிடம் அதையே சொன்னேன். பிறகு அவர் ஸஃபிய்யா (ரழி) அவர்களைச் சந்தித்தபோது, அவரும் அவ்வாறே கூறினார். மீண்டும் அவர் ஹஃப்ஸா (ரழி) அவர்களிடம் சென்றபோது, 'அல்லாஹ்வின் தூதரே, நான் உங்களுக்கு மீண்டும் அந்தப் பானத்தைத் தரட்டுமா?' என்று அவர் கேட்டார். அதற்கு நபி (ஸல்) அவர்கள்,\"<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">حَاجَةَ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">فِيه</span>»<br />\r\n<br />\r\n(எனக்கு அது தேவையில்லை) என்றார்கள். \"அல்லாஹ்வின் மீது ஆணையாக! நாம் அவரைத் தேன் குடிப்பதைத் தடுத்துவிட்டோம்\" என்று ஸவ்தா (ரழி) கூறினார். நான் அவரிடம், \"அமைதியாக இரு!\" என்று சொன்னேன். இமாம் முஸ்லிமும் (ரஹ்) இந்த ஹதீஸைப் பதிவு செய்துள்ளார், ஆனால் இந்த வாசகங்கள் புகாரியுடையது. முஸ்லிமின் அறிவிப்பில், ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம்மிலிருந்து கெட்ட வாடை வருவதை மிகவும் வெறுப்பார்கள்.\" அதனால்தான் அவர்கள் அவர் மஃகாஃபீர் சாப்பிட்டதாகக் கூறினார்கள், ஏனெனில் அது கெட்ட வாடையை உண்டாக்கும்.<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">شَرِبْتُ</span> <span class=\"quran-arabic-font text-success\">عَسَلًا</span>»<br />\r\n<br />\r\n(இல்லை, நான் சிறிது தேன் அருந்தினேன்) என்று நபி (ஸல்) அவர்கள் கூறியபோது, தேனீக்கள் அல்-உர்ஃபுத் எனப்படும் மரத்திலிருந்து உண்டிருக்கலாம், அதன் பிசினால்தான் இந்த வாடை வந்திருக்கும் என்று அவர்கள் குறிப்பிட்டனர். உர்வா வழியாக வரும் ஆயிஷா (ரழி) அவர்களின் அறிவிப்பில், ஹஃப்ஸா (ரழி) அவர்களே தேன் கொடுத்ததாகக் குறிப்பிடப்பட்டுள்ளது. உபைத் பின் உமைர் வழியாக வரும் மற்றோர் அறிவிப்பில், ஜைனப் பின்த் ஜஹ்ஷ் (ரழி) அவர்களே தேன் கொடுத்தார் என்றும், ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) ஆகியோரே சதி செய்தவர்கள் என்றும் உள்ளது. அல்லாஹ்வே மிக அறிந்தவன். சிலர் இவை இரண்டு தனித்தனி சம்பவங்கள் என்று கூறலாம். இருப்பினும், அவை தனித்தனி சம்பவங்களாக இருந்தால், இரண்டுக்கும் சேர்த்து இந்த வசனங்கள் அருளப்பட்டிருக்க வாய்ப்பில்லை. அல்லாஹ்வே மிக அறிந்தவன். இமாம் அஹ்மத் (ரஹ்) அவர்கள் தனது முஸ்னதில் தொகுத்துள்ள ஹதீஸிலும் ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) ஆகியோரே அந்தத் தந்திரத்தைச் செய்தவர்கள் என்று குறிப்பிடப்பட்டுள்ளது.<br />\r\n<br />\r\nஇமாம் அஹ்மத் (ரஹ்) பதிவு செய்துள்ளார்கள்: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ் யாரைப் பற்றி,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَتُوبَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">صَغَتْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبُكُمَا</span><br />\r\n<br />\r\n(நீங்கள் இருவரும் அல்லாஹ்விடம் பாவமன்னிப்புத் தேடினால் (அது உங்களுக்கு நலம்); ஏனெனில் உங்கள் இருவருடைய உள்ளங்களும் (சத்தியத்திலிருந்து) நிச்சயமாகச் சாய்ந்துவிட்டன) என்று கூறினானோ, நபி (ஸல்) அவர்களின் மனைவியரில் அந்த இருவரைப் பற்றி உமர் (ரழி) அவர்களிடம் கேட்க நான் ஆவலாக இருந்தேன். பிறகு நான் உமர் (ரழி) அவர்களுடன் ஹஜ் பயணம் மேற்கொண்டேன். ஹஜ் முடிந்து திரும்பும் வழியில் அவர் (இயற்கைக் கடனை நிறைவேற்ற) ஒதுங்கிச் சென்றார். நானும் அவருடன் ஒரு குவளைத் தண்ணீரைச் சுமந்து சென்றேன். அவர் கடமையை முடித்துத் திரும்பியதும், அவர் கைகளில் தண்ணீர் ஊற்றினேன்; அவர் வுழூ செய்தார். நான் கேட்டேன்: 'அமீருல் முஃமினீன் அவர்களே! நபி (ஸல்) அவர்களின் மனைவியரில் அல்லாஹ் குர்ஆனில் யாரைக் குறிப்பிடுகிறானோ, அந்த இரு பெண்கள் யார்?' உமர் (ரழி) அவர்கள், 'இப்னு அப்பாஸே! உமது கேள்வியைக் கண்டு நான் வியப்படைகிறேன்' என்று கூறினார்கள்.\" - அஸ்-ஸுஹ்ரி கூறுகிறார்: உமர் (ரழி) அவர்களுக்கு இந்தக் கேள்வி பிடிக்கவில்லை என்றாலும், அவர்கள் ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) என்று பதிலளித்தார்கள். பிறகு உமர் (ரழி) அவர்கள் கதையைத் தொடர்ந்தார்கள்: \"நாங்கள் குறைஷி சமூகத்தைச் சேர்ந்தவர்கள்; எங்களின் பெண்கள் மீது எங்களுக்கு ஆதிக்கம் இருந்தது. ஆனால் நாங்கள் மதீனாவிற்கு வந்து அன்சாரித் தோழர்களுடன் வாழத் தொடங்கியபோது, அன்சாரிப் பெண்கள் தங்கள் ஆண்கள் மீது மேலாதிக்கம் செலுத்துவதைக் கண்டோம். எனவே, எங்கள் பெண்களும் அன்சாரிப் பெண்களின் பழக்கங்களைக் கற்றுக்கொள்ளத் தொடங்கினர். அந்த நேரத்தில் நான் அல்-அவாலி பகுதியில் உமைய்யா பின் ஸைத் என்பவரின் வீட்டில் தங்கியிருந்தேன். ஒருமுறை நான் என் மனைவி மீது கோபப்பட்டபோது, அவள் எனக்குப் பதில் பேசினாள். அவள் பதில் பேசுவதை நான் விரும்பவில்லை. அதற்கு அவள், 'நான் உங்களுக்குப் பதில் பேசுவதை ஏன் நீங்கள் வெறுக்கிறீர்கள்? அல்லாஹ்வின் மீது ஆணையாக! நபி (ஸல்) அவர்களின் மனைவிகள் அவருக்கே பதில் பேசுகிறார்கள். அவர்களில் சிலர் பகல் முழுவதும் இரவு வரை அவருடன் பேசாமல் கூட இருப்பார்கள்' என்று சொன்னாள். உடனே நான் ஹஃப்ஸா (ரழி) அவர்களிடம் சென்று, 'நீ அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் பதில் பேசுகிறாயா?' என்று கேட்டேன். அவர் 'ஆம்' என்றார். 'உங்களில் எவராவது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களை நாள் முழுவதும் கோபமாக வைத்திருக்கின்றீர்களா?' என்று கேட்டேன். அவர் 'ஆம்' என்று பதிலளித்தார். 'உங்களில் யார் இப்படிச் செய்தாலும் அவர் நஷ்டமடைந்து அழிந்து போவார்! அல்லாஹ்வின் தூதரின் கோபத்தால் அல்லாஹ்வும் தன் மீது கோபம்கொள்வான், அதனால் தான் அழிந்துவிடுவோம் என்று அவளுக்கு அச்சம் இல்லையா? அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் எதையும் அதிகமாகக் கேட்காதே; எந்தச் சூழ்நிலையிலும் அவரிடம் எதிர்த்துப் பேசாதே. உனக்குத் தேவையானதை என்னிடம் கேள். உனது அண்டை வீட்டாருக்கு இருக்கும் அழகையும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர் மீது வைத்திருக்கும் பிரியத்தையும் பார்த்து அவரைப் போல் நடக்க ஆசைப்படாதே' என்று எச்சரித்தேன்.\" அவர் ஆயிஷா (ரழி) அவர்களையே அவ்வாறு குறிப்பிட்டார்.<br />\r\n<br />\r\nநானும் எனது அன்சாரி அண்டை வீட்டாருமாக முறை வைத்துக்கொண்டு நபி (ஸல்) அவர்களைச் சந்திப்போம். ஒரு நாள் அவர் செல்வார், மறுநாள் நான் செல்வேன். நான் செல்லும்போது அன்றைய தினம் அருளப்பட்ட வஹீ (இறைச்செய்தி) பற்றிய தகவல்களை அவருக்குச் சொல்வேன். அவர் செல்லும்போது அவரும் அவ்வாறே எனக்குச் சொல்வார். அந்த நாட்களில் கஸ்ஸான் கோத்திரத்தார் எங்களைத் தாக்குவதற்குத் தயாராகி வருவதாக ஒரு வதந்தி பரவியிருந்தது. ஒரு நாள் இரவு என் நண்பர் வந்து என் கதவைத் தட்டினார். நான் வெளியே வந்தபோது, ஒரு பெரிய விஷயம் நடந்துவிட்டதாக அவர் சொன்னார். 'என்ன நடந்தது? கஸ்ஸானியர்கள் வந்துவிட்டார்களா?' என்று நான் கேட்டேன். 'இல்லை, அதை விட மோசமான ஒன்று நடந்துவிட்டது; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் மனைவிகள் அனைவரையும் விவாகரத்து செய்துவிட்டார்கள்' என்று அவர் கூறினார். 'ஹஃப்ஸா நஷ்டமடைந்துவிட்டாள்! இது ஒரு நாள் நடக்கும் என்று நான் முன்பே எதிர்பார்த்தேன்' என்று நான் சொன்னேன். விடிந்ததும் சுப்ஹு தொழுகையை முடித்துவிட்டு ஹஃப்ஸா (ரழி) அவர்களிடம் சென்றேன். அவர் அழுதுகொண்டிருந்தார். 'அல்லாஹ்வின் தூதர் (ஸல்) உங்கள் அனைவரையும் விவாகரத்து செய்துவிட்டார்களா?' என்று கேட்டேன். அதற்கு அவர், 'எனக்குத் தெரியாது, அவர்கள் அந்த மாடி அறையில் தனியாக இருக்கிறார்கள்' என்றார். நான் அங்கு சென்று நபி (ஸல்) அவர்களின் கருப்பினப் பணியாளரிடம் அனுமதி கேட்டேன். அவர் உள்ளே சென்றுவிட்டு வந்து, 'நான் உங்களைப் பற்றி அவரிடம் சொன்னேன், ஆனால் அவர் மௌனமாக இருந்தார்' என்றார். நான் அங்கிருந்து வெளியேறி மிம்பருக்கு வந்தேன். அங்கு மக்கள் குழுமியிருந்து அழுதுகொண்டிருந்தனர். என்னால் அந்த நிலையைத் தாங்க முடியவில்லை. மீண்டும் அந்தப் பணியாளரிடம் சென்று உமருக்காக அனுமதி கேட்டேன். அவர் உள்ளே சென்றுவிட்டு அதே பதிலைச் சொன்னார். நான் மீண்டும் திரும்பிச் செல்லும்போது அவர் என்னை அழைத்து, 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உங்களுக்கு அனுமதி அளித்துவிட்டார்கள்' என்றார். நான் உள்ளே சென்று நபி (ஸல்) அவர்களுக்கு ஸலாம் கூறினேன். அவர் ஒரு பாயின் மீது படுத்திருந்தார். அதன் மீது எந்த விரிப்பும் இல்லை. அந்தப் பாயின் அடையாளங்கள் அவர் திருமேனியில் பதிந்திருந்தன.<br />\r\n<br />\r\nநான் கேட்டேன்: 'அல்லாஹ்வின் தூதரே! நீங்கள் உங்கள் மனைவியரை விவாகரத்து செய்துவிட்டீர்களா?' அவர் தன் கண்களை உயர்த்தி 'இல்லை' என்று பதிலளித்தார். 'அல்லாஹு அக்பர்!' என்று நான் கூறினேன். பிறகு சொன்னேன்: 'அல்லாஹ்வின் தூதரே! குறைஷிகளாகிய நாங்கள் எங்கள் பெண்களை அடக்கி வைத்திருந்தோம். ஆனால் மதீனாவிற்கு வந்தபோது, இங்கிருப்பவர்களின் பெண்கள் அவர்கள் மீது ஆதிக்கம் செலுத்துவதைக் கண்டோம். எமது பெண்களும் அதைப்பார்த்துப் பழகிக்கொண்டனர். நான் என் மனைவி மீது கோபப்பட்டபோது அவள் எனக்குப் பதில் பேசினாள். அதை நான் வெறுத்தபோது, அவள் 'ஏன் வெறுக்கிறீர்கள்? அல்லாஹ்வின் தூதரின் மனைவிகளே அவருக்குப் பதில் பேசுகிறார்கள்; அவர்களில் ஒருவர் நாள் முழுவதும் அவரைப் புறக்கணித்துக் கூட இருக்கிறார்' என்று சொன்னாள். 'அவர்களில் யார் அப்படிச் செய்தாலும் அவர் நஷ்டவாளி; அல்லாஹ்வின் கோபத்திற்கு அவர் அஞ்ச வேண்டாமா?' என்று அவளிடம் சொன்னேன்.' இதைக் கேட்டு நபி (ஸல்) அவர்கள் புன்னகைத்தார்கள். மீண்டும் நான் சொன்னேன்: 'அல்லாஹ்வின் தூதரே! நான் ஹஃப்ஸாவிடம் சென்று, அழகிலும் உங்கள் அன்பிலும் சிறந்து விளங்கும் உமது தோழியை (ஆயிஷாவை) முன்மாதிரியாகக் கொள்ளாதே என்று சொன்னேன்.' அப்போதும் நபி (ஸல்) அவர்கள் புன்னகைத்தார்கள். அவர் அமைதியாக இருப்பதைப் பார்த்து நான் அமர்ந்தேன். அந்த அறையைச் சுற்றிப் பார்த்தேன். அல்லாஹ்வின் மீது ஆணையாக! அங்கே பதப்படுத்தப்பட்ட மூன்று தோல் பைகளைத் தவிர வேறெந்த முக்கியமான பொருட்களையும் என்னால் காண முடியவில்லை. நான் சொன்னேன்: 'அல்லாஹ்வின் தூதரே! பாரசீகர்களும் ரோமானியர்களும் அல்லாஹ்வை வணங்காதவர்களாக இருந்தும் உலகச் செழிப்போடு வாழ்கிறார்கள். எனவே, உங்கள் உம்மத்தினரைச் செழிப்பாக்க அல்லாஹ்விடம் துஆ செய்யுங்கள்.' நபி (ஸல்) அவர்கள் நிமிர்ந்து உட்கார்ந்து,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَفِي</span> <span class=\"quran-arabic-font text-success\">شَكَ</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">ابْنَ</span> <span class=\"quran-arabic-font text-success\">الْخَطَّابِ</span> <span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">عُجِّلَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">طَيِّبَاتُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span>»<br />\r\n<br />\r\n(கத்தாபின் மகனே! உனக்கு இதில் ஏதும் சந்தேகம் இருக்கிறதா? அவர்கள் இவ்வுலக வாழ்விலேயே தங்களின் நன்மைகளுக்கான கூலிகளைப் பெற்றுக்கொண்ட மக்கள்) என்று பதிலளித்தார்கள். \"அல்லாஹ்வின் தூதரே! எனக்காக மன்னிப்புக் கோருங்கள்\" என்று நான் வேண்டினேன். நபி (ஸல்) அவர்கள் தம் மனைவியர் மீது கொண்ட கோபத்தால் ஒரு மாதம் வரை அவர்களிடம் செல்வதில்லை என்று சத்தியம் செய்திருந்தார்கள். பிறகு மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் அவர்களைக் கண்டிக்கும் வரை இந்நிலை நீடித்தது.\" அல்-புகாரி, முஸ்லிம், திர்மிதி மற்றும் நஸாயீ ஆகியோரும் பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாக இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். அல்-புகாரி மற்றும் முஸ்லிம் அவர்களும் இப்னு அப்பாஸ் (ரழி) வழியாக இதைத் தொகுத்துள்ளனர். அவர் கூறினார்: \"ஒரு வருடம் முழுவதும் நான் உமர் பின் அல்-கத்தாப் (ரழி) அவர்களிடம் அந்த வசனத்தைப் பற்றிக் கேட்க விரும்பினேன்; ஆனால் அவர் மீதான மரியாதையால் தயங்கினேன். ஒருமுறை அவர் ஹஜ் பயணத்தில் இருந்தபோது நானும் அவருடன் சென்றேன். திரும்பி வரும்போது 'அராக்' மரங்களுக்குப் பின்னால் அவர் ஒதுங்கியபோது நான் அவருக்காகக் காத்திருந்தேன். அவர் வந்ததும், 'நம்பிக்கையாளர்களின் தலைவரே! நபி (ஸல்) அவர்களுக்கு எதிராகச் சதி செய்த அந்த இரு பெண்கள் யார்?' என்று கேட்டேன்.\" புகாரியின் அறிவிப்பு இதுவாகும். முஸ்லிமின் அறிவிப்பில், அல்லாஹ் யாரைக் குறித்து<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">تَظَاهَرَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span><br />\r\n<br />\r\n(ஆனால் நீங்கள் இருவரும் அவருக்கு எதிராக ஒருவருக்கொருவர் உதவி செய்துகொண்டால், ) என்று கூறினானோ அந்த இருவர் யார் என்று இப்னு அப்பாஸ் (ரழி) கேட்டதற்கு, உமர் (ரழி) அவர்கள் \"ஆயிஷா மற்றும் ஹஃப்ஸா\" என்று பதிலளித்ததாக உள்ளது. இமாம் முஸ்லிம் ஹதீஸின் மீதமுள்ள பகுதியை விவரித்துள்ளார். இமாம் முஸ்லிம் (ரஹ்) இப்னு அப்பாஸ் (ரழி) வழியாகப் பதிவு செய்துள்ளார்: உமர் (ரழி) அவர்கள் கூறினார்கள்: \"நபி (ஸல்) அவர்கள் தம் மனைவியரிடமிருந்து ஒதுங்கியிருந்தபோது, நான் மஸ்ஜிதுக்குள் நுழைந்தேன். மக்கள் தரையில் சிறு கற்களைக் கொண்டு தட்டிக்கொண்டிருந்தனர். 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் மனைவியரை விவாகரத்து செய்துவிட்டார்கள்' என்று அவர்கள் பேசிக்கொண்டிருந்தனர். இது ஹிஜாப் சட்டம் அருளப்படுவதற்கு முன் நடந்த விஷயமாகும். 'இன்று நான் இதைப்பற்றி விசாரித்தே தீர வேண்டும்' என்று எனக்குள் சொன்னேன்.\" பிறகு ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) ஆகியோருக்கு அவர் அறிவுரை கூறிய ஹதீஸைக் குறிப்பிட்டார். \"நான் உள்ளே சென்றபோது, நபி (ஸல்) அவர்களின் பணியாளர் ரபாஹ் ஜன்னல் ஓரத்தில் அமர்ந்திருப்பதை நான் கண்டேன். 'ரபாஹ்! எனக்காக அல்லாஹ்வின் தூதரிடம் அனுமதி கேள்' என்று சொன்னேன்.\" பிறகு முன்பு கூறியது போலவே கதையை விவரித்தார். உமர் (ரழி) தொடர்ந்தார்கள்: \"அல்லாஹ்வின் தூதரே! உங்கள் மனைவிகளால் உங்களுக்கு என்ன சிரமம்? நீங்கள் அவர்களை விவாகரத்து செய்தாலும், நிச்சயமாக அல்லாஹ் உங்களுடன் இருக்கிறான். அவனது வானவர்களும், ஜிப்ரீல், மீகால், நான், அபூபக்ர் மற்றும் முஃமின்களில் நல்லோர்களும் உங்களுடன் இருக்கிறோம்' என்று சொன்னேன். பெரும்பாலும் நான் பேசும்போது - அல்லாஹ்வுக்கே புகழனைத்தும் - எனது வார்த்தைகளை அல்லாஹ் உறுதிப்படுத்துவான் என்று நான் நம்புவேன். அவ்வாறே 'தேர்வு செய்தல்' (விருப்பத் தேர்வு) தொடர்பான வசனங்கள் அருளப்பட்டன.\" அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَسَى</span> <span class=\"quran-arabic-font text-success\">رَبُّهُ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">طَلَّقَكُنَّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُبْدِلَهُ</span> <span class=\"quran-arabic-font text-success\">أَزْوَجاً</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">مِّنكُنَّ</span><br />\r\n<br />\r\n(அவர் உங்களை விவாகரத்துச் செய்துவிட்டால், உங்களைவிடச் சிறந்த மனைவியரை அவருடைய இறைவன் அவருக்கு மாற்றாக வழங்கக்கூடும்,) மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">تَظَاهَرَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">مَوْلَـهُ</span> <span class=\"quran-arabic-font text-success\">وَجِبْرِيلُ</span> <span class=\"quran-arabic-font text-success\">وَصَـلِحُ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمَلَـئِكَةُ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">ظَهِيرٌ</span><br />\r\n<br />\r\n(ஆனால் நீங்கள் அவருக்கு எதிராக ஒருவருக்கொருவர் உதவி செய்துகொண்டால், நிச்சயமாக அல்லாஹ்வே அவருக்குப் பாதுகாவலன்; ஜிப்ரீலும் முஃமின்களில் நல்லோர்களும் (அவருக்குப் பாதுகாவலர்களே). அதற்குப் பிறகு வானவர்களும் அவருக்கு உதவியாளர்களாக இருப்பார்கள்.) நான் 'அல்லாஹ்வின் தூதரே! நீங்கள் அவர்களை விவாகரத்து செய்துவிட்டீர்களா?' என்று கேட்டேன். அவர் 'இல்லை' என்றார். நான் மஸ்ஜித் வாசலில் நின்று சத்தமாக, 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் மனைவியரை விவாகரத்து செய்யவில்லை' என்று அறிவித்தேன். இந்தச் சந்தர்ப்பத்தில்தான் பின்வரும் வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَمْرٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الاٌّمْنِ</span> <span class=\"quran-arabic-font text-success\">أَوِ</span> <span class=\"quran-arabic-font text-success\">الْخَوْفِ</span> <span class=\"quran-arabic-font text-success\">أَذَاعُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">رَدُّوهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">وَإِلَى</span> <span class=\"quran-arabic-font text-success\">أُوْلِى</span> <span class=\"quran-arabic-font text-success\">الاٌّمْرِ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">لَعَلِمَهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَنْبِطُونَهُ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span><br />\r\n<br />\r\n(அமைதி அல்லது அச்சம் குறித்த செய்தி அவர்களுக்கு வரும்போது, அதை அவர்கள் பரப்புகிறார்கள்; அதைத் தூதரிடமோ அல்லது அவர்களில் அதிகாரம் உள்ளவர்களிடமோ அவர்கள் கொண்டு சென்றால், அவர்களில் உண்மையைக் கண்டறியும் திறன் உள்ளவர்கள் அதைச் சரியாகப் புரிந்துகொள்வார்கள்.) (<a href=\"qurandisp.php?sura=4&ayah=83\" class=\"link\">4:83</a>) \"இந்த விஷயத்தை நானே சரியாகப் புரிந்துகொண்டு விசாரித்தேன்\" என்று உமர் (ரழி) கூறினார். இதே கருத்தைச் சயீத் பின் ஜுபைர், இக்ரிமா, முகாத்தில் பின் ஹய்யான், அத்-தஹ்ஹாக் போன்றோரும் கூறியுள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَصَـلِحُ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span><br />\r\n<br />\r\n(முஃமின்களில் நல்லோர்கள்) என்பது அபூபக்ர் (ரழி) மற்றும் உமர் (ரழி) ஆகியோரைக் குறிக்கும். ஹஸன் அல்-பஸரி (ரஹ்) அவர்கள் உஸ்மான் (ரழி) அவர்களையும் இதில் சேர்த்துக் குறிப்பிடுகிறார். முஜாஹித் (ரஹ்) வழியாக லைஸ் பின் அபீ சுலைம் கூறும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَصَـلِحُ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span><br />\r\n<br />\r\n(முஃமின்களில் நல்லோர்கள்) என்பதில் அலீ பின் அபீ தாலிப் (ரழி) அவர்களும் அடங்குவர் என்று கூறுகிறார். இமாம் புகாரி (ரஹ்) பதிவு செய்துள்ளார்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: \"உமர் (ரழி) அவர்கள் கூறினார்கள்: 'நபி (ஸல்) அவர்களின் மனைவிகள் அனைவரும் அவர் மீது கொண்ட பொறாமையால் ஒன்று திரண்டபோது நான் அவர்களிடம் சொன்னேன்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَسَى</span> <span class=\"quran-arabic-font text-success\">رَبُّهُ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">طَلَّقَكُنَّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُبْدِلَهُ</span> <span class=\"quran-arabic-font text-success\">أَزْوَجاً</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">مِّنكُنَّ</span><br />\r\n<br />\r\n(அவர் உங்களை விவாகரத்துச் செய்துவிட்டால், உங்களைவிடச் சிறந்த மனைவியரை அவருடைய இறைவன் அவருக்கு மாற்றாக வழங்கக்கூடும்.) அதன் பிறகு இந்த வசனம் அருளப்பட்டது.\" உமர் (ரழி) அவர்கள் கூறிய பல கருத்துக்களைக் குர்ஆன் உறுதிப்படுத்தியுள்ளது என்று நாம் முன்பே பார்த்தோம். உதாரணமாக ஹிஜாப் தொடர்பான வசனம் (பார்க்க <a href=\"qurandisp.php?sura=33&ayah=53\" class=\"link\">33:53</a>), பத்ருப் போர்க்கைதிகள் தொடர்பான வசனம் (பார்க்க <a href=\"qurandisp.php?sura=8&ayah=67\" class=\"link\">8:67</a>) மற்றும் இப்ராஹீம் (அலை) அவர்கள் நின்ற இடத்தைத் தொழும் இடமாக ஆக்குமாறு உமர் (ரழி) அவர்கள் செய்த பரிந்துரை ஆகியவற்றைச் சொல்லலாம்; அதற்குப் பிறகு அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاتَّخِذُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّقَامِ</span> <span class=\"quran-arabic-font text-success\">إِبْرَهِيمَ</span> <span class=\"quran-arabic-font text-success\">مُصَلًّى</span><br />\r\n<br />\r\n(இப்ராஹீமின் இடத்தை (மகாமை) நீங்கள் தொழும் இடமாக ஆக்கிக்கொள்ளுங்கள்.) (<a href=\"qurandisp.php?sura=2&ayah=125\" class=\"link\">2:125</a>) இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"இறைநம்பிக்கையாளர்களின் அன்னையர்கள் நபி (ஸல்) அவர்களுடன் விவாதித்ததாக எனக்குச் செய்தி கிடைத்தது. நான் அவர்களிடம் சென்று, 'நீங்கள் நபி (ஸல்) அவர்களைத் தொந்தரவு செய்வதை நிறுத்துங்கள்; இல்லையெனில் அல்லாஹ் அவருக்கு உங்களை விடச் சிறந்த மனைவியரை வழங்கிவிடுவான்' என்று அறிவுரை கூறினேன்.\" இதே கருத்தை ஹஸன் அல்-பஸரி (ரஹ்) அவர்கள் உஸ்மான் (ரழி) அவர்களையும் சேர்த்துத் தெரிவிக்கிறார். முஜாஹித் (ரஹ்) வழியாக லைஸ் பின் அபீ சுலைம் கூறும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَصَـلِحُ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span><br />\r\n<br />\r\n(முஃமின்களில் நல்லோர்கள்) என்பதில் அலீ பின் அபீ தாலிப் (ரழி) அவர்களும் அடங்குவர் என்று கூறுகிறார். இமாம் புகாரி (ரஹ்) பதிவு செய்துள்ளார்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: \"உமர் (ரழி) அவர்கள் கூறினார்கள்: 'நபி (ஸல்) அவர்களின் மனைவிகள் அனைவரும் அவர் மீது கொண்ட பொறாமையால் ஒன்று திரண்டபோது நான் அவர்களிடம் சொன்னேன்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَسَى</span> <span class=\"quran-arabic-font text-success\">رَبُّهُ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">طَلَّقَكُنَّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُبْدِلَهُ</span> <span class=\"quran-arabic-font text-success\">أَزْوَجاً</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">مِّنكُنَّ</span><br />\r\n<br />\r\n(அவர் உங்களை விவாகரத்துச் செய்துவிட்டால், உங்களைவிடச் சிறந்த மனைவியரை அவருடைய இறைவன் அவருக்கு மாற்றாக வழங்கக்கூடும்.) அதன் பிறகு இந்த வசனம் அருளப்பட்டது.\" உமர் (ரழி) அவர்கள் கூறிய பல கருத்துக்களைக் குர்ஆன் உறுதிப்படுத்தியுள்ளது என்று நாம் முன்பே பார்த்தோம். உதாரணமாக ஹிஜாப் தொடர்பான வசனம் (பார்க்க <a href=\"qurandisp.php?sura=33&ayah=53\" class=\"link\">33:53</a>), பத்ருப் போர்க்கைதிகள் தொடர்பான வசனம் (பார்க்க <a href=\"qurandisp.php?sura=8&ayah=67\" class=\"link\">8:67</a>) மற்றும் இப்ராஹீம் (அலை) அவர்கள் நின்ற இடத்தைத் தொழும் இடமாக ஆக்குமாறு உமர் (ரழி) அவர்கள் செய்த பரிந்துரை ஆகியவற்றைச் சொல்லலாம்; அதற்குப் பிறகு அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاتَّخِذُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّقَامِ</span> <span class=\"quran-arabic-font text-success\">إِبْرَهِيمَ</span> <span class=\"quran-arabic-font text-success\">مُصَلًّى</span><br />\r\n<br />\r\n(இப்ராஹீமின் இடத்தை (மகாமை) நீங்கள் தொழும் இடமாக ஆக்கிக்கொள்ளுங்கள்.) (<a href=\"qurandisp.php?sura=2&ayah=125\" class=\"link\">2:125</a>) இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"இறைநம்பிக்கையாளர்களின் அன்னையர்கள் நபி (ஸல்) அவர்களுடன் விவாதித்ததாக எனக்குச் செய்தி கிடைத்தது. நான் அவர்களிடம் சென்று, 'நீங்கள் நபி (ஸல்) அவர்களைத் தொந்தரவு செய்வதை நிறுத்துங்கள்; இல்லையெனில் அல்லாஹ் அவருக்கு உங்களை விடச் சிறந்த மனைவியரை வழங்கிவிடுவான்' என்று அறிவுரை கூறினேன்.\" இவ்வாறு அபூ அப்துர்-ரஹ்மான் அஸ்-ஸுலமி, அபூ மாலிக், இப்ராஹீம் அந்-நகஈ, ஹஸன், கத்தாதா, அத்-தஹ்ஹாக், அர்-ரபீஃ பின் அனஸ், அஸ்-ஸுத்தி மற்றும் பலரும் கூறியுள்ளனர்.<br />\r\n<br />","text":"மதீனாவில் அருளப்பட்டது\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\n\r\n\n\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.)\n\r\n\n\r\nவேதம் அவருக்கு அனுமதித்த ஒரு காரியத்தை நபி (ஸல்) அவர்கள் தமக்குத் தாமே தடுத்துக் கொண்டதற்காக அல்லாஹ் அவர்களைக் கண்டிக்கிறான்\n\r\n\n\r\nஅல்-புகாரி (ரஹ்) பதிவு செய்துள்ளார்கள்: உபைத் பின் உமைர் அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஜைனப் பின்த் ஜஹ்ஷ் (ரழி) அவர்களின் இல்லத்தில் சிறிது நேரம் தங்கி, அங்கு தேன் அருந்துவது வழக்கம் என்று ஆயிஷா (ரழி) அவர்கள் கூறியதாக நான் கேள்விப்பட்டேன். (ஆயிஷா (ரழி) மேலும் கூறினார்கள்:) \"நபி (ஸல்) அவர்கள் எங்களில் யாரிடம் நுழைந்தாலும், 'உங்களிடமிருந்து மஃகாஃபீரின் வாடை வீசுகிறதே, நீங்கள் மஃகாஃபீர் (ஒரு வகை பிசின்) சாப்பிட்டீர்களா?' என்று கேட்க நானும் ஹஃப்ஸா (ரழி) அவர்களும் முடிவு செய்தோம். நபி (ஸல்) அவர்கள் எங்களில் ஒருவரிடம் வந்தபோது, அவர் அவ்வாறே கேட்டார். அதற்கு நபி (ஸல்) அவர்கள்,\"\n\r\n\n\r\n«لَا، بَلْ شَرِبْتُ عَسَلًا عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ وَلَنْ أَعُودَ لَه»\n\r\n\n\r\n(இல்லை, நான் ஜைனப் பின்த் ஜஹ்ஷ் (ரழி) அவர்களின் வீட்டில் தேன் அருந்தினேன். இனி நான் அதை அருந்தவே மாட்டேன்) என்று பதிலளித்தார்கள். அதன் பிறகு பின்வரும் வசனங்கள் அருளப்பட்டன:\n\r\n\n\r\nيأَيُّهَا النَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ اللَّهُ لَكَ\n\r\n\n\r\n(நபியே! அல்லாஹ் உமக்கு அனுமதித்ததை நீர் ஏன் தடுத்துக் கொள்கிறீர்) என்பது முதல்,\n\r\n\n\r\nإِن تَتُوبَآ إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا\n\r\n\n\r\n(நீங்கள் இருவரும் அல்லாஹ்விடம் பாவமன்னிப்புத் தேடினால் (அது உங்களுக்கு நலம்); ஏனெனில் உங்கள் இருவருடைய உள்ளங்களும் (சத்தியத்திலிருந்து) நிச்சயமாகச் சாய்ந்துவிட்டன) என்பது வரை. இது ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) ஆகியோரைக் குறிப்பிடுகிறது.\n\r\n\n\r\nوَإِذَ أَسَرَّ النَّبِىُّ إِلَى بَعْضِ أَزْوَجِهِ حَدِيثاً\n\r\n\n\r\n(நபி தம் மனைவியரில் ஒருவரிடம் ஒரு செய்தியை இரகசியமாகக் கூறியபோது (நினைவுகூருங்கள்)) - இது நபி (ஸல்) அவர்களின் இந்தக் கூற்றைக் குறிக்கிறது:\n\r\n\n\r\n«بَلْ شَرِبْتُ عَسَلًا»\n\r\n\n\r\n(நான் தேன் அருந்தினேன்.) இப்ராஹீம் பின் மூஸா, ஹிஷாம் வழியாகக் கூறும்போது, இது நபி (ஸல்) அவர்களின் இந்தக் கூற்றையும் குறிக்கும் என்று கூறுகிறார்:\n\r\n\n\r\n«وَلَنْ أَعُودَ لَهُ وَقَدْ حَلَفْتُ فَلَا تُخْبِرِي بِذَلِكِ أَحَدًا»\n\r\n\n\r\n(இனிமேல் நான் அதை அருந்த மாட்டேன், இதற்காக நான் சத்தியம் செய்துள்ளேன். எனவே, இதை யாரிடமும் சொல்ல வேண்டாம்.) அல்-புகாரி (ரஹ்) இந்த ஹதீஸை விவாகரத்து (தலாக்) அத்தியாயத்திலும் பதிவு செய்துள்ளார்கள். பிறகு அவர், \"மஃகாஃபீர் என்பது மரத்திலிருந்து வடியும் ஒரு வகை பிசின்; 'அர்-ரிம்த்' எனும் செடியில் அதன் சுவை இனிப்பாக இருக்கும்...\" என்று கூறுகிறார். அல்-ஜவ்ஹரி கூறுகிறார்: \"உர்ஃபுத் என்பது ஒரு வகை புதர்ச் செடி, அது மக்ஃபூரைச் சுரக்கும்.\" இமாம் முஸ்லிம் (ரஹ்) இந்த ஹதீஸை ஆயிஷா (ரழி) அவர்களின் அறிவிப்பாகத் தனது ஸஹீஹில் விவாகரத்து அத்தியாயத்தில் பதிவு செய்துள்ளார். அதன் வாசகம், புகாரியின் நேர்ச்சைகள் அத்தியாயத்தில் உள்ள வாசகத்தைப் போன்றதே. விவாகரத்து அத்தியாயத்தில் அல்-புகாரி (ரஹ்) பதிவு செய்துள்ள மற்றோர் அறிவிப்பில் ஆயிஷா (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு இனிப்புகளும் தேனும் மிகவும் பிடிக்கும். அஸர் தொழுகைக்குப் பிறகு அவர்கள் தம் மனைவியரைச் சந்தித்து, அவர்களுடன் நெருக்கமாக இருப்பது வழக்கம். ஒருமுறை ஹஃப்ஸா (ரழி) அவர்களின் அறைக்குச் சென்று, வழக்கத்தை விட அதிக நேரம் தங்கினார்கள். நான் (ஆயிஷா (ரழி)) பொறாமைப்பட்டு அதைப் பற்றி விசாரித்தேன். 'அவருடைய குடும்பத்தைச் சேர்ந்த ஒரு பெண் அவருக்கு ஒரு சிறிய பாத்திரத்தில் தேனைப் பரிசாக அனுப்பியுள்ளார், அதிலிருந்து அவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்குப் பானம் தயாரித்துக் கொடுத்தார்' என்று எனக்குத் தெரிவிக்கப்பட்டது. நான் சொன்னேன்: 'அல்லாஹ்வின் மீது ஆணையாக! நாம் அவருக்கு எதிராக ஒரு தந்திரம் செய்வோம்.' பிறகு நான் ஸவ்தா பின்த் ஜம்ஆ (ரழி) அவர்களிடம் சொன்னேன்: 'நபி (ஸல்) அவர்கள் உங்களிடம் வந்து நெருங்கும்போது, 'நீங்கள் மஃகாஃபீர் சாப்பிட்டீர்களா?' என்று கேளுங்கள். அவர் 'இல்லை' என்று கூறும்போது, 'அப்படியானால் இந்த வாடை என்ன?' என்று கேளுங்கள். அவர் 'ஹஃப்ஸா எனக்குத் தேன் குடிக்கக் கொடுத்தார்' என்று கூறுவார். அப்போது நீங்கள், 'தேனீக்கள் உர்ஃபுத் செடியிலிருந்து உண்டிருக்கலாம்' என்று சொல்லுங்கள். நானும் அவரிடம் அதையே சொல்வேன். ஸஃபிய்யா (ரழி), நீங்களும் இதையே சொல்லுங்கள்.' ஸவ்தா (ரழி) பின்னர் கூறினார்கள்: 'அல்லாஹ்வின் மீது ஆணையாக! நீங்கள் சொன்னதைச் சொல்வதற்கு நான் தயங்கினேன்; ஆனால் அதற்குள்ளாகவே நபி (ஸல்) அவர்கள் என் வாசலில் வந்து நின்றார்கள்.' அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரிடம் நெருங்கியபோது, 'அல்லாஹ்வின் தூதரே! நீங்கள் மஃகாஃபீர் சாப்பிட்டீர்களா?' என்று அவர் கேட்டார். அவர் 'இல்லை' என்றார்கள். 'அப்படியானால் இந்த வாடை என்ன?' என்று அவர் மீண்டும் கேட்டார். அதற்கு நபி (ஸல்) அவர்கள்,\"\n\r\n\n\r\n«سَقَتْنِي حَفْصَةُ شَرْبَةَ عَسَل»\n\r\n\n\r\n(ஹஃப்ஸா எனக்குத் தேன் குடிக்கக் கொடுத்தார்) என்றார்கள். அதற்கு ஸவ்தா (ரழி), 'தேனீக்கள் உர்ஃபுத் செடியிலிருந்து உண்டிருக்கலாம்' என்றார்.\" ஆயிஷா (ரழி) அவர்கள் தொடர்ந்தார்கள்: \"நபி (ஸல்) அவர்கள் என்னிடம் வந்தபோது நானும் அவரிடம் அதையே சொன்னேன். பிறகு அவர் ஸஃபிய்யா (ரழி) அவர்களைச் சந்தித்தபோது, அவரும் அவ்வாறே கூறினார். மீண்டும் அவர் ஹஃப்ஸா (ரழி) அவர்களிடம் சென்றபோது, 'அல்லாஹ்வின் தூதரே, நான் உங்களுக்கு மீண்டும் அந்தப் பானத்தைத் தரட்டுமா?' என்று அவர் கேட்டார். அதற்கு நபி (ஸல்) அவர்கள்,\"\n\r\n\n\r\n«لَا حَاجَةَ لِي فِيه»\n\r\n\n\r\n(எனக்கு அது தேவையில்லை) என்றார்கள். \"அல்லாஹ்வின் மீது ஆணையாக! நாம் அவரைத் தேன் குடிப்பதைத் தடுத்துவிட்டோம்\" என்று ஸவ்தா (ரழி) கூறினார். நான் அவரிடம், \"அமைதியாக இரு!\" என்று சொன்னேன். இமாம் முஸ்லிமும் (ரஹ்) இந்த ஹதீஸைப் பதிவு செய்துள்ளார், ஆனால் இந்த வாசகங்கள் புகாரியுடையது. முஸ்லிமின் அறிவிப்பில், ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம்மிலிருந்து கெட்ட வாடை வருவதை மிகவும் வெறுப்பார்கள்.\" அதனால்தான் அவர்கள் அவர் மஃகாஃபீர் சாப்பிட்டதாகக் கூறினார்கள், ஏனெனில் அது கெட்ட வாடையை உண்டாக்கும்.\n\r\n\n\r\n«بَلْ شَرِبْتُ عَسَلًا»\n\r\n\n\r\n(இல்லை, நான் சிறிது தேன் அருந்தினேன்) என்று நபி (ஸல்) அவர்கள் கூறியபோது, தேனீக்கள் அல்-உர்ஃபுத் எனப்படும் மரத்திலிருந்து உண்டிருக்கலாம், அதன் பிசினால்தான் இந்த வாடை வந்திருக்கும் என்று அவர்கள் குறிப்பிட்டனர். உர்வா வழியாக வரும் ஆயிஷா (ரழி) அவர்களின் அறிவிப்பில், ஹஃப்ஸா (ரழி) அவர்களே தேன் கொடுத்ததாகக் குறிப்பிடப்பட்டுள்ளது. உபைத் பின் உமைர் வழியாக வரும் மற்றோர் அறிவிப்பில், ஜைனப் பின்த் ஜஹ்ஷ் (ரழி) அவர்களே தேன் கொடுத்தார் என்றும், ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) ஆகியோரே சதி செய்தவர்கள் என்றும் உள்ளது. அல்லாஹ்வே மிக அறிந்தவன். சிலர் இவை இரண்டு தனித்தனி சம்பவங்கள் என்று கூறலாம். இருப்பினும், அவை தனித்தனி சம்பவங்களாக இருந்தால், இரண்டுக்கும் சேர்த்து இந்த வசனங்கள் அருளப்பட்டிருக்க வாய்ப்பில்லை. அல்லாஹ்வே மிக அறிந்தவன். இமாம் அஹ்மத் (ரஹ்) அவர்கள் தனது முஸ்னதில் தொகுத்துள்ள ஹதீஸிலும் ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) ஆகியோரே அந்தத் தந்திரத்தைச் செய்தவர்கள் என்று குறிப்பிடப்பட்டுள்ளது.\n\r\n\n\r\nஇமாம் அஹ்மத் (ரஹ்) பதிவு செய்துள்ளார்கள்: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ் யாரைப் பற்றி,\n\r\n\n\r\nإِن تَتُوبَآ إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا\n\r\n\n\r\n(நீங்கள் இருவரும் அல்லாஹ்விடம் பாவமன்னிப்புத் தேடினால் (அது உங்களுக்கு நலம்); ஏனெனில் உங்கள் இருவருடைய உள்ளங்களும் (சத்தியத்திலிருந்து) நிச்சயமாகச் சாய்ந்துவிட்டன) என்று கூறினானோ, நபி (ஸல்) அவர்களின் மனைவியரில் அந்த இருவரைப் பற்றி உமர் (ரழி) அவர்களிடம் கேட்க நான் ஆவலாக இருந்தேன். பிறகு நான் உமர் (ரழி) அவர்களுடன் ஹஜ் பயணம் மேற்கொண்டேன். ஹஜ் முடிந்து திரும்பும் வழியில் அவர் (இயற்கைக் கடனை நிறைவேற்ற) ஒதுங்கிச் சென்றார். நானும் அவருடன் ஒரு குவளைத் தண்ணீரைச் சுமந்து சென்றேன். அவர் கடமையை முடித்துத் திரும்பியதும், அவர் கைகளில் தண்ணீர் ஊற்றினேன்; அவர் வுழூ செய்தார். நான் கேட்டேன்: 'அமீருல் முஃமினீன் அவர்களே! நபி (ஸல்) அவர்களின் மனைவியரில் அல்லாஹ் குர்ஆனில் யாரைக் குறிப்பிடுகிறானோ, அந்த இரு பெண்கள் யார்?' உமர் (ரழி) அவர்கள், 'இப்னு அப்பாஸே! உமது கேள்வியைக் கண்டு நான் வியப்படைகிறேன்' என்று கூறினார்கள்.\" - அஸ்-ஸுஹ்ரி கூறுகிறார்: உமர் (ரழி) அவர்களுக்கு இந்தக் கேள்வி பிடிக்கவில்லை என்றாலும், அவர்கள் ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) என்று பதிலளித்தார்கள். பிறகு உமர் (ரழி) அவர்கள் கதையைத் தொடர்ந்தார்கள்: \"நாங்கள் குறைஷி சமூகத்தைச் சேர்ந்தவர்கள்; எங்களின் பெண்கள் மீது எங்களுக்கு ஆதிக்கம் இருந்தது. ஆனால் நாங்கள் மதீனாவிற்கு வந்து அன்சாரித் தோழர்களுடன் வாழத் தொடங்கியபோது, அன்சாரிப் பெண்கள் தங்கள் ஆண்கள் மீது மேலாதிக்கம் செலுத்துவதைக் கண்டோம். எனவே, எங்கள் பெண்களும் அன்சாரிப் பெண்களின் பழக்கங்களைக் கற்றுக்கொள்ளத் தொடங்கினர். அந்த நேரத்தில் நான் அல்-அவாலி பகுதியில் உமைய்யா பின் ஸைத் என்பவரின் வீட்டில் தங்கியிருந்தேன். ஒருமுறை நான் என் மனைவி மீது கோபப்பட்டபோது, அவள் எனக்குப் பதில் பேசினாள். அவள் பதில் பேசுவதை நான் விரும்பவில்லை. அதற்கு அவள், 'நான் உங்களுக்குப் பதில் பேசுவதை ஏன் நீங்கள் வெறுக்கிறீர்கள்? அல்லாஹ்வின் மீது ஆணையாக! நபி (ஸல்) அவர்களின் மனைவிகள் அவருக்கே பதில் பேசுகிறார்கள். அவர்களில் சிலர் பகல் முழுவதும் இரவு வரை அவருடன் பேசாமல் கூட இருப்பார்கள்' என்று சொன்னாள். உடனே நான் ஹஃப்ஸா (ரழி) அவர்களிடம் சென்று, 'நீ அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் பதில் பேசுகிறாயா?' என்று கேட்டேன். அவர் 'ஆம்' என்றார். 'உங்களில் எவராவது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களை நாள் முழுவதும் கோபமாக வைத்திருக்கின்றீர்களா?' என்று கேட்டேன். அவர் 'ஆம்' என்று பதிலளித்தார். 'உங்களில் யார் இப்படிச் செய்தாலும் அவர் நஷ்டமடைந்து அழிந்து போவார்! அல்லாஹ்வின் தூதரின் கோபத்தால் அல்லாஹ்வும் தன் மீது கோபம்கொள்வான், அதனால் தான் அழிந்துவிடுவோம் என்று அவளுக்கு அச்சம் இல்லையா? அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் எதையும் அதிகமாகக் கேட்காதே; எந்தச் சூழ்நிலையிலும் அவரிடம் எதிர்த்துப் பேசாதே. உனக்குத் தேவையானதை என்னிடம் கேள். உனது அண்டை வீட்டாருக்கு இருக்கும் அழகையும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர் மீது வைத்திருக்கும் பிரியத்தையும் பார்த்து அவரைப் போல் நடக்க ஆசைப்படாதே' என்று எச்சரித்தேன்.\" அவர் ஆயிஷா (ரழி) அவர்களையே அவ்வாறு குறிப்பிட்டார்.\n\r\n\n\r\nநானும் எனது அன்சாரி அண்டை வீட்டாருமாக முறை வைத்துக்கொண்டு நபி (ஸல்) அவர்களைச் சந்திப்போம். ஒரு நாள் அவர் செல்வார், மறுநாள் நான் செல்வேன். நான் செல்லும்போது அன்றைய தினம் அருளப்பட்ட வஹீ (இறைச்செய்தி) பற்றிய தகவல்களை அவருக்குச் சொல்வேன். அவர் செல்லும்போது அவரும் அவ்வாறே எனக்குச் சொல்வார். அந்த நாட்களில் கஸ்ஸான் கோத்திரத்தார் எங்களைத் தாக்குவதற்குத் தயாராகி வருவதாக ஒரு வதந்தி பரவியிருந்தது. ஒரு நாள் இரவு என் நண்பர் வந்து என் கதவைத் தட்டினார். நான் வெளியே வந்தபோது, ஒரு பெரிய விஷயம் நடந்துவிட்டதாக அவர் சொன்னார். 'என்ன நடந்தது? கஸ்ஸானியர்கள் வந்துவிட்டார்களா?' என்று நான் கேட்டேன். 'இல்லை, அதை விட மோசமான ஒன்று நடந்துவிட்டது; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் மனைவிகள் அனைவரையும் விவாகரத்து செய்துவிட்டார்கள்' என்று அவர் கூறினார். 'ஹஃப்ஸா நஷ்டமடைந்துவிட்டாள்! இது ஒரு நாள் நடக்கும் என்று நான் முன்பே எதிர்பார்த்தேன்' என்று நான் சொன்னேன். விடிந்ததும் சுப்ஹு தொழுகையை முடித்துவிட்டு ஹஃப்ஸா (ரழி) அவர்களிடம் சென்றேன். அவர் அழுதுகொண்டிருந்தார். 'அல்லாஹ்வின் தூதர் (ஸல்) உங்கள் அனைவரையும் விவாகரத்து செய்துவிட்டார்களா?' என்று கேட்டேன். அதற்கு அவர், 'எனக்குத் தெரியாது, அவர்கள் அந்த மாடி அறையில் தனியாக இருக்கிறார்கள்' என்றார். நான் அங்கு சென்று நபி (ஸல்) அவர்களின் கருப்பினப் பணியாளரிடம் அனுமதி கேட்டேன். அவர் உள்ளே சென்றுவிட்டு வந்து, 'நான் உங்களைப் பற்றி அவரிடம் சொன்னேன், ஆனால் அவர் மௌனமாக இருந்தார்' என்றார். நான் அங்கிருந்து வெளியேறி மிம்பருக்கு வந்தேன். அங்கு மக்கள் குழுமியிருந்து அழுதுகொண்டிருந்தனர். என்னால் அந்த நிலையைத் தாங்க முடியவில்லை. மீண்டும் அந்தப் பணியாளரிடம் சென்று உமருக்காக அனுமதி கேட்டேன். அவர் உள்ளே சென்றுவிட்டு அதே பதிலைச் சொன்னார். நான் மீண்டும் திரும்பிச் செல்லும்போது அவர் என்னை அழைத்து, 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உங்களுக்கு அனுமதி அளித்துவிட்டார்கள்' என்றார். நான் உள்ளே சென்று நபி (ஸல்) அவர்களுக்கு ஸலாம் கூறினேன். அவர் ஒரு பாயின் மீது படுத்திருந்தார். அதன் மீது எந்த விரிப்பும் இல்லை. அந்தப் பாயின் அடையாளங்கள் அவர் திருமேனியில் பதிந்திருந்தன.\n\r\n\n\r\nநான் கேட்டேன்: 'அல்லாஹ்வின் தூதரே! நீங்கள் உங்கள் மனைவியரை விவாகரத்து செய்துவிட்டீர்களா?' அவர் தன் கண்களை உயர்த்தி 'இல்லை' என்று பதிலளித்தார். 'அல்லாஹு அக்பர்!' என்று நான் கூறினேன். பிறகு சொன்னேன்: 'அல்லாஹ்வின் தூதரே! குறைஷிகளாகிய நாங்கள் எங்கள் பெண்களை அடக்கி வைத்திருந்தோம். ஆனால் மதீனாவிற்கு வந்தபோது, இங்கிருப்பவர்களின் பெண்கள் அவர்கள் மீது ஆதிக்கம் செலுத்துவதைக் கண்டோம். எமது பெண்களும் அதைப்பார்த்துப் பழகிக்கொண்டனர். நான் என் மனைவி மீது கோபப்பட்டபோது அவள் எனக்குப் பதில் பேசினாள். அதை நான் வெறுத்தபோது, அவள் 'ஏன் வெறுக்கிறீர்கள்? அல்லாஹ்வின் தூதரின் மனைவிகளே அவருக்குப் பதில் பேசுகிறார்கள்; அவர்களில் ஒருவர் நாள் முழுவதும் அவரைப் புறக்கணித்துக் கூட இருக்கிறார்' என்று சொன்னாள். 'அவர்களில் யார் அப்படிச் செய்தாலும் அவர் நஷ்டவாளி; அல்லாஹ்வின் கோபத்திற்கு அவர் அஞ்ச வேண்டாமா?' என்று அவளிடம் சொன்னேன்.' இதைக் கேட்டு நபி (ஸல்) அவர்கள் புன்னகைத்தார்கள். மீண்டும் நான் சொன்னேன்: 'அல்லாஹ்வின் தூதரே! நான் ஹஃப்ஸாவிடம் சென்று, அழகிலும் உங்கள் அன்பிலும் சிறந்து விளங்கும் உமது தோழியை (ஆயிஷாவை) முன்மாதிரியாகக் கொள்ளாதே என்று சொன்னேன்.' அப்போதும் நபி (ஸல்) அவர்கள் புன்னகைத்தார்கள். அவர் அமைதியாக இருப்பதைப் பார்த்து நான் அமர்ந்தேன். அந்த அறையைச் சுற்றிப் பார்த்தேன். அல்லாஹ்வின் மீது ஆணையாக! அங்கே பதப்படுத்தப்பட்ட மூன்று தோல் பைகளைத் தவிர வேறெந்த முக்கியமான பொருட்களையும் என்னால் காண முடியவில்லை. நான் சொன்னேன்: 'அல்லாஹ்வின் தூதரே! பாரசீகர்களும் ரோமானியர்களும் அல்லாஹ்வை வணங்காதவர்களாக இருந்தும் உலகச் செழிப்போடு வாழ்கிறார்கள். எனவே, உங்கள் உம்மத்தினரைச் செழிப்பாக்க அல்லாஹ்விடம் துஆ செய்யுங்கள்.' நபி (ஸல்) அவர்கள் நிமிர்ந்து உட்கார்ந்து,\n\r\n\n\r\n«أَفِي شَكَ أَنْتَ يَا ابْنَ الْخَطَّابِ أُولَئِكَ قَوْمٌ عُجِّلَتْ لَهُمْ طَيِّبَاتُهُمْ فِي الْحَيَاةِ الدُّنْيَا»\n\r\n\n\r\n(கத்தாபின் மகனே! உனக்கு இதில் ஏதும் சந்தேகம் இருக்கிறதா? அவர்கள் இவ்வுலக வாழ்விலேயே தங்களின் நன்மைகளுக்கான கூலிகளைப் பெற்றுக்கொண்ட மக்கள்) என்று பதிலளித்தார்கள். \"அல்லாஹ்வின் தூதரே! எனக்காக மன்னிப்புக் கோருங்கள்\" என்று நான் வேண்டினேன். நபி (ஸல்) அவர்கள் தம் மனைவியர் மீது கொண்ட கோபத்தால் ஒரு மாதம் வரை அவர்களிடம் செல்வதில்லை என்று சத்தியம் செய்திருந்தார்கள். பிறகு மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் அவர்களைக் கண்டிக்கும் வரை இந்நிலை நீடித்தது.\" அல்-புகாரி, முஸ்லிம், திர்மிதி மற்றும் நஸாயீ ஆகியோரும் பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாக இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். அல்-புகாரி மற்றும் முஸ்லிம் அவர்களும் இப்னு அப்பாஸ் (ரழி) வழியாக இதைத் தொகுத்துள்ளனர். அவர் கூறினார்: \"ஒரு வருடம் முழுவதும் நான் உமர் பின் அல்-கத்தாப் (ரழி) அவர்களிடம் அந்த வசனத்தைப் பற்றிக் கேட்க விரும்பினேன்; ஆனால் அவர் மீதான மரியாதையால் தயங்கினேன். ஒருமுறை அவர் ஹஜ் பயணத்தில் இருந்தபோது நானும் அவருடன் சென்றேன். திரும்பி வரும்போது 'அராக்' மரங்களுக்குப் பின்னால் அவர் ஒதுங்கியபோது நான் அவருக்காகக் காத்திருந்தேன். அவர் வந்ததும், 'நம்பிக்கையாளர்களின் தலைவரே! நபி (ஸல்) அவர்களுக்கு எதிராகச் சதி செய்த அந்த இரு பெண்கள் யார்?' என்று கேட்டேன்.\" புகாரியின் அறிவிப்பு இதுவாகும். முஸ்லிமின் அறிவிப்பில், அல்லாஹ் யாரைக் குறித்து\n\r\n\n\r\nوَإِن تَظَاهَرَا عَلَيْهِ\n\r\n\n\r\n(ஆனால் நீங்கள் இருவரும் அவருக்கு எதிராக ஒருவருக்கொருவர் உதவி செய்துகொண்டால், ) என்று கூறினானோ அந்த இருவர் யார் என்று இப்னு அப்பாஸ் (ரழி) கேட்டதற்கு, உமர் (ரழி) அவர்கள் \"ஆயிஷா மற்றும் ஹஃப்ஸா\" என்று பதிலளித்ததாக உள்ளது. இமாம் முஸ்லிம் ஹதீஸின் மீதமுள்ள பகுதியை விவரித்துள்ளார். இமாம் முஸ்லிம் (ரஹ்) இப்னு அப்பாஸ் (ரழி) வழியாகப் பதிவு செய்துள்ளார்: உமர் (ரழி) அவர்கள் கூறினார்கள்: \"நபி (ஸல்) அவர்கள் தம் மனைவியரிடமிருந்து ஒதுங்கியிருந்தபோது, நான் மஸ்ஜிதுக்குள் நுழைந்தேன். மக்கள் தரையில் சிறு கற்களைக் கொண்டு தட்டிக்கொண்டிருந்தனர். 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் மனைவியரை விவாகரத்து செய்துவிட்டார்கள்' என்று அவர்கள் பேசிக்கொண்டிருந்தனர். இது ஹிஜாப் சட்டம் அருளப்படுவதற்கு முன் நடந்த விஷயமாகும். 'இன்று நான் இதைப்பற்றி விசாரித்தே தீர வேண்டும்' என்று எனக்குள் சொன்னேன்.\" பிறகு ஆயிஷா (ரழி) மற்றும் ஹஃப்ஸா (ரழி) ஆகியோருக்கு அவர் அறிவுரை கூறிய ஹதீஸைக் குறிப்பிட்டார். \"நான் உள்ளே சென்றபோது, நபி (ஸல்) அவர்களின் பணியாளர் ரபாஹ் ஜன்னல் ஓரத்தில் அமர்ந்திருப்பதை நான் கண்டேன். 'ரபாஹ்! எனக்காக அல்லாஹ்வின் தூதரிடம் அனுமதி கேள்' என்று சொன்னேன்.\" பிறகு முன்பு கூறியது போலவே கதையை விவரித்தார். உமர் (ரழி) தொடர்ந்தார்கள்: \"அல்லாஹ்வின் தூதரே! உங்கள் மனைவிகளால் உங்களுக்கு என்ன சிரமம்? நீங்கள் அவர்களை விவாகரத்து செய்தாலும், நிச்சயமாக அல்லாஹ் உங்களுடன் இருக்கிறான். அவனது வானவர்களும், ஜிப்ரீல், மீகால், நான், அபூபக்ர் மற்றும் முஃமின்களில் நல்லோர்களும் உங்களுடன் இருக்கிறோம்' என்று சொன்னேன். பெரும்பாலும் நான் பேசும்போது - அல்லாஹ்வுக்கே புகழனைத்தும் - எனது வார்த்தைகளை அல்லாஹ் உறுதிப்படுத்துவான் என்று நான் நம்புவேன். அவ்வாறே 'தேர்வு செய்தல்' (விருப்பத் தேர்வு) தொடர்பான வசனங்கள் அருளப்பட்டன.\" அல்லாஹ் கூறினான்:\n\r\n\n\r\nعَسَى رَبُّهُ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُ أَزْوَجاً خَيْراً مِّنكُنَّ\n\r\n\n\r\n(அவர் உங்களை விவாகரத்துச் செய்துவிட்டால், உங்களைவிடச் சிறந்த மனைவியரை அவருடைய இறைவன் அவருக்கு மாற்றாக வழங்கக்கூடும்,) மேலும்,\n\r\n\n\r\nوَإِن تَظَاهَرَا عَلَيْهِ فَإِنَّ اللَّهَ هُوَ مَوْلَـهُ وَجِبْرِيلُ وَصَـلِحُ الْمُؤْمِنِينَ وَالْمَلَـئِكَةُ بَعْدَ ذَلِكَ ظَهِيرٌ\n\r\n\n\r\n(ஆனால் நீங்கள் அவருக்கு எதிராக ஒருவருக்கொருவர் உதவி செய்துகொண்டால், நிச்சயமாக அல்லாஹ்வே அவருக்குப் பாதுகாவலன்; ஜிப்ரீலும் முஃமின்களில் நல்லோர்களும் (அவருக்குப் பாதுகாவலர்களே). அதற்குப் பிறகு வானவர்களும் அவருக்கு உதவியாளர்களாக இருப்பார்கள்.) நான் 'அல்லாஹ்வின் தூதரே! நீங்கள் அவர்களை விவாகரத்து செய்துவிட்டீர்களா?' என்று கேட்டேன். அவர் 'இல்லை' என்றார். நான் மஸ்ஜித் வாசலில் நின்று சத்தமாக, 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் மனைவியரை விவாகரத்து செய்யவில்லை' என்று அறிவித்தேன். இந்தச் சந்தர்ப்பத்தில்தான் பின்வரும் வசனம் அருளப்பட்டது:\n\r\n\n\r\nوَإِذَا جَآءَهُمْ أَمْرٌ مِّنَ الاٌّمْنِ أَوِ الْخَوْفِ أَذَاعُواْ بِهِ وَلَوْ رَدُّوهُ إِلَى الرَّسُولِ وَإِلَى أُوْلِى الاٌّمْرِ مِنْهُمْ لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ\n\r\n\n\r\n(அமைதி அல்லது அச்சம் குறித்த செய்தி அவர்களுக்கு வரும்போது, அதை அவர்கள் பரப்புகிறார்கள்; அதைத் தூதரிடமோ அல்லது அவர்களில் அதிகாரம் உள்ளவர்களிடமோ அவர்கள் கொண்டு சென்றால், அவர்களில் உண்மையைக் கண்டறியும் திறன் உள்ளவர்கள் அதைச் சரியாகப் புரிந்துகொள்வார்கள்.) (4:83) \"இந்த விஷயத்தை நானே சரியாகப் புரிந்துகொண்டு விசாரித்தேன்\" என்று உமர் (ரழி) கூறினார். இதே கருத்தைச் சயீத் பின் ஜுபைர், இக்ரிமா, முகாத்தில் பின் ஹய்யான், அத்-தஹ்ஹாக் போன்றோரும் கூறியுள்ளனர்.\n\r\n\n\r\nوَصَـلِحُ الْمُؤْمِنِينَ\n\r\n\n\r\n(முஃமின்களில் நல்லோர்கள்) என்பது அபூபக்ர் (ரழி) மற்றும் உமர் (ரழி) ஆகியோரைக் குறிக்கும். ஹஸன் அல்-பஸரி (ரஹ்) அவர்கள் உஸ்மான் (ரழி) அவர்களையும் இதில் சேர்த்துக் குறிப்பிடுகிறார். முஜாஹித் (ரஹ்) வழியாக லைஸ் பின் அபீ சுலைம் கூறும்போது,\n\r\n\n\r\nوَصَـلِحُ الْمُؤْمِنِينَ\n\r\n\n\r\n(முஃமின்களில் நல்லோர்கள்) என்பதில் அலீ பின் அபீ தாலிப் (ரழி) அவர்களும் அடங்குவர் என்று கூறுகிறார். இமாம் புகாரி (ரஹ்) பதிவு செய்துள்ளார்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: \"உமர் (ரழி) அவர்கள் கூறினார்கள்: 'நபி (ஸல்) அவர்களின் மனைவிகள் அனைவரும் அவர் மீது கொண்ட பொறாமையால் ஒன்று திரண்டபோது நான் அவர்களிடம் சொன்னேன்:\n\r\n\n\r\nعَسَى رَبُّهُ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُ أَزْوَجاً خَيْراً مِّنكُنَّ\n\r\n\n\r\n(அவர் உங்களை விவாகரத்துச் செய்துவிட்டால், உங்களைவிடச் சிறந்த மனைவியரை அவருடைய இறைவன் அவருக்கு மாற்றாக வழங்கக்கூடும்.) அதன் பிறகு இந்த வசனம் அருளப்பட்டது.\" உமர் (ரழி) அவர்கள் கூறிய பல கருத்துக்களைக் குர்ஆன் உறுதிப்படுத்தியுள்ளது என்று நாம் முன்பே பார்த்தோம். உதாரணமாக ஹிஜாப் தொடர்பான வசனம் (பார்க்க 33:53), பத்ருப் போர்க்கைதிகள் தொடர்பான வசனம் (பார்க்க 8:67) மற்றும் இப்ராஹீம் (அலை) அவர்கள் நின்ற இடத்தைத் தொழும் இடமாக ஆக்குமாறு உமர் (ரழி) அவர்கள் செய்த பரிந்துரை ஆகியவற்றைச் சொல்லலாம்; அதற்குப் பிறகு அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nوَاتَّخِذُواْ مِن مَّقَامِ إِبْرَهِيمَ مُصَلًّى\n\r\n\n\r\n(இப்ராஹீமின் இடத்தை (மகாமை) நீங்கள் தொழும் இடமாக ஆக்கிக்கொள்ளுங்கள்.) (2:125) இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"இறைநம்பிக்கையாளர்களின் அன்னையர்கள் நபி (ஸல்) அவர்களுடன் விவாதித்ததாக எனக்குச் செய்தி கிடைத்தது. நான் அவர்களிடம் சென்று, 'நீங்கள் நபி (ஸல்) அவர்களைத் தொந்தரவு செய்வதை நிறுத்துங்கள்; இல்லையெனில் அல்லாஹ் அவருக்கு உங்களை விடச் சிறந்த மனைவியரை வழங்கிவிடுவான்' என்று அறிவுரை கூறினேன்.\" இதே கருத்தை ஹஸன் அல்-பஸரி (ரஹ்) அவர்கள் உஸ்மான் (ரழி) அவர்களையும் சேர்த்துத் தெரிவிக்கிறார். முஜாஹித் (ரஹ்) வழியாக லைஸ் பின் அபீ சுலைம் கூறும்போது,\n\r\n\n\r\nوَصَـلِحُ الْمُؤْمِنِينَ\n\r\n\n\r\n(முஃமின்களில் நல்லோர்கள்) என்பதில் அலீ பின் அபீ தாலிப் (ரழி) அவர்களும் அடங்குவர் என்று கூறுகிறார். இமாம் புகாரி (ரஹ்) பதிவு செய்துள்ளார்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: \"உமர் (ரழி) அவர்கள் கூறினார்கள்: 'நபி (ஸல்) அவர்களின் மனைவிகள் அனைவரும் அவர் மீது கொண்ட பொறாமையால் ஒன்று திரண்டபோது நான் அவர்களிடம் சொன்னேன்:\n\r\n\n\r\nعَسَى رَبُّهُ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُ أَزْوَجاً خَيْراً مِّنكُنَّ\n\r\n\n\r\n(அவர் உங்களை விவாகரத்துச் செய்துவிட்டால், உங்களைவிடச் சிறந்த மனைவியரை அவருடைய இறைவன் அவருக்கு மாற்றாக வழங்கக்கூடும்.) அதன் பிறகு இந்த வசனம் அருளப்பட்டது.\" உமர் (ரழி) அவர்கள் கூறிய பல கருத்துக்களைக் குர்ஆன் உறுதிப்படுத்தியுள்ளது என்று நாம் முன்பே பார்த்தோம். உதாரணமாக ஹிஜாப் தொடர்பான வசனம் (பார்க்க 33:53), பத்ருப் போர்க்கைதிகள் தொடர்பான வசனம் (பார்க்க 8:67) மற்றும் இப்ராஹீம் (அலை) அவர்கள் நின்ற இடத்தைத் தொழும் இடமாக ஆக்குமாறு உமர் (ரழி) அவர்கள் செய்த பரிந்துரை ஆகியவற்றைச் சொல்லலாம்; அதற்குப் பிறகு அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nوَاتَّخِذُواْ مِن مَّقَامِ إِبْرَهِيمَ مُصَلًّى\n\r\n\n\r\n(இப்ராஹீமின் இடத்தை (மகாமை) நீங்கள் தொழும் இடமாக ஆக்கிக்கொள்ளுங்கள்.) (2:125) இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"இறைநம்பிக்கையாளர்களின் அன்னையர்கள் நபி (ஸல்) அவர்களுடன் விவாதித்ததாக எனக்குச் செய்தி கிடைத்தது. நான் அவர்களிடம் சென்று, 'நீங்கள் நபி (ஸல்) அவர்களைத் தொந்தரவு செய்வதை நிறுத்துங்கள்; இல்லையெனில் அல்லாஹ் அவருக்கு உங்களை விடச் சிறந்த மனைவியரை வழங்கிவிடுவான்' என்று அறிவுரை கூறினேன்.\" இவ்வாறு அபூ அப்துர்-ரஹ்மான் அஸ்-ஸுலமி, அபூ மாலிக், இப்ராஹீம் அந்-நகஈ, ஹஸன், கத்தாதா, அத்-தஹ்ஹாக், அர்-ரபீஃ பின் அனஸ், அஸ்-ஸுத்தி மற்றும் பலரும் கூறியுள்ளனர்."},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=66&ayah=8\" class=\"link\">66:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 66:8 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=66&ayah=8\" class=\"link\">66:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 66:8 ஐ பார்க்கவும்"},"8":{"html":"<strong>தன் குடும்பத்தாருக்கு மார்க்கத்தையும் நற்பண்புகளையும் கற்பித்தல்</strong><br />\r\n<br />\r\nஅலி பின் அபி தல்ஹா (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُوا</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَهْلِيكُمْ</span> <span class=\"quran-arabic-font text-success\">نَارًا</span><br />\r\n<br />\r\n(உங்களையும் உங்கள் குடும்பத்தினரையும் நரக நெருப்பிலிருந்து பாதுகாத்துக் கொள்ளுங்கள்) என்ற வசனத்திற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அல்லாஹ்வுக்குக் கீழ்ப்படிந்து நடங்கள், அல்லாஹ்வுக்கு மாறு செய்வதைத் தவிர்த்துக் கொள்ளுங்கள். உங்கள் குடும்பத்தினரை அல்லாஹ்வை நினைவு கூருமாறு ஏவுங்கள்; அப்போது அல்லாஹ் உங்களை நரக நெருப்பிலிருந்து காப்பாற்றுவான்\" என்று விளக்கமளித்தார்கள். முஜாஹித் (ரழி) அவர்களும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُوا</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَهْلِيكُمْ</span> <span class=\"quran-arabic-font text-success\">نَارًا</span><br />\r\n<br />\r\n(உங்களையும் உங்கள் குடும்பத்தினரையும் நரக நெருப்பிலிருந்து பாதுகாத்துக் கொள்ளுங்கள்) என்ற வசனத்திற்கு, \"அல்லாஹ்வை அஞ்சிக் கொள்ளுங்கள் (தக்வா), உங்கள் குடும்பத்தினரையும் அவனை அஞ்சுமாறு ஏவுங்கள்\" என்று விளக்கமளித்தார்கள். கதாதா (ரழி) அவர்கள் கூறும்போது, \"ஒருவர் அல்லாஹ்வுக்குக் கீழ்ப்படியுமாறு ஏவ வேண்டும், அவனுக்கு மாறு செய்வதைத் தவிர்க்க வேண்டும். தனது குடும்பத்தினரை அவனது கட்டளைகளுக்குப் பணியுமாறு ஏவி, அதன்படி செயல்பட அவர்களுக்கு உதவ வேண்டும். அவர்கள் ஏதேனும் மாறு செய்வதைக் கண்டால், அதைத் தடுத்து அவர்களை விலக்க வேண்டும்\" என்றார்கள். இதே போன்ற கருத்தை அத்-தஹ்ஹாக் மற்றும் முகாத்தில் (ரழி) அவர்களும் கூறியுள்ளனர்; \"அல்லாஹ் எவற்றை அவர்கள் மீது கடமையாக்கினானோ, எவற்றைத் தடை செய்துள்ளானோ, அவற்றை ஒரு முஸ்லிம் தனது நெருங்கிய உறவினர்களுக்கும், தனது ஆண் மற்றும் பெண் அடிமைகளுக்கும் கற்பிப்பது கடமையாகும்.\" இந்த வசனத்தின் பொருளை உறுதிப்படுத்தும் ஒரு ஹதீஸ் உள்ளது. அஹ்மத், அபூ தாவூத் மற்றும் அத்-திர்மிதி ஆகியோர் பதிவு செய்துள்ள ஹதீஸில், அர்-ரபீ பின் சப்ரா (ரழி) அவர்கள் தனது தந்தை கூறியதாக அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مُرُوا</span> <span class=\"quran-arabic-font text-success\">الصَّبِيَّ</span> <span class=\"quran-arabic-font text-success\">بِالصَّلَاةِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">سِنِينَ،</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span> <span class=\"quran-arabic-font text-success\">عَشْرَ</span> <span class=\"quran-arabic-font text-success\">سِنِينَ</span> <span class=\"quran-arabic-font text-success\">فَاضْرِبُوهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span>»<br />\r\n<br />\r\n(குழந்தைகள் ஏழு வயதை அடையும் போது அவர்களைத் தொழுமாறு ஏவுங்கள்; பத்து வயதை அடையும் போது (தொழுகையை நிறைவேற்றாவிட்டால்) அதற்காக அவர்களை அடியுங்கள்.) இது அபூ தாவூத் பதிவு செய்த அறிவிப்பாகும்; அத்-திர்மிதி இது \"ஹஸன்\" தரத்திலான ஹதீஸ் என்று குறிப்பிட்டுள்ளார்.<br />\r\n<br />\r\n<strong>நரகத்தின் எரிபொருளும் அதன் வானவர்களின் வர்ணனையும்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقُودُهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">وَالْحِجَارَةُ</span><br />\r\n<br />\r\n(அதன் எரிபொருள் மனிதர்களும் கற்களுமாகும்,) ஆதமின் மக்கள் அந்த நரக நெருப்பை வளர்க்கும் எரிபொருளாக இருப்பார்கள் என்பதை இது குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْحِجَارَةُ</span><br />\r\n<br />\r\n(மற்றும் கற்கள்) என்பது வணங்கப்பட்டு வந்த சிலைகளைக் குறிக்கிறது. இதை அல்லாஹ் மற்றொரு வசனத்தில் பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">حَصَبُ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span><br />\r\n<br />\r\n(நிச்சயமாக நீங்களும், அல்லாஹ்வையன்றி நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருளே!) (<a href=\"qurandisp.php?sura=21&ayah=98\" class=\"link\">21:98</a>). அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி), முஜாஹித் (ரழி), அபூ ஜஃபர் அல்-பாகிர் (ரழி) மற்றும் அஸ்-சுத்தி (ரழி) ஆகியோர் இவை கந்தகக் கற்கள் என்று கூறுகின்றனர். இவை (வானத்தையும் பூமியையும் படைத்தபோதே அல்லாஹ் படைத்துவிட்ட) கந்தகக் கற்கள் என்றும், இவை அழுகிய பிணங்களை விடவும் அதிக துர்நாற்றம் வீசக்கூடியவை என்று முஜாஹித் (ரழி) குறிப்பிடுகிறார்கள். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">مَلَائِكَةٌ</span> <span class=\"quran-arabic-font text-success\">غِلَاظٌ</span> <span class=\"quran-arabic-font text-success\">شِدَادٌ</span><br />\r\n<br />\r\n(அதன் மீது கடுமையானவர்களும் வலிமையானவர்களுமான வானவர்கள் (நியமிக்கப்பட்டு) இருக்கிறார்கள்,) அதாவது, அவர்களின் குணம் மிகவும் கடுமையானது; ஏனெனில் அல்லாஹ்வை நிராகரிப்பவர்கள் மீது இரக்கம் கொள்வது அவர்களின் இதயங்களிலிருந்து நீக்கப்பட்டுவிட்டது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">شِدَادٌ</span><br />\r\n<br />\r\n(வலிமையானவர்கள்) அதாவது, அவர்களின் உடலமைப்பு மிகவும் ஆற்றல் மிக்கதும், அச்சமூட்டக்கூடியதும் ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّا</span> <span class=\"quran-arabic-font text-success\">يَعْصُونَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَمَرَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَيَفْعَلُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُؤْمَرُونَ</span><br />\r\n<br />\r\n(அல்லாஹ் தங்களுக்கு இட்ட கட்டளைகளுக்கு அவர்கள் மாறு செய்வதில்லை; தங்களுக்குக் கட்டளையிடப்பட்டதையே அவர்கள் செய்கிறார்கள்.) அதாவது, அல்லாஹ் அவர்களுக்கு எதை ஏவினாலும், அவர்கள் ஒரு கண் இமைக்கும் நேரம்கூட தாமதிக்காமல் அவனுக்குக் கீழ்ப்படிய விரைந்து செல்வார்கள். அத்தகைய கட்டளைகளை நிறைவேற்றும் ஆற்றல் கொண்ட அவர்கள் 'அஸ்-ஸபானியா' (நரகத்தின் காவலர்கள்) என்று அழைக்கப்படுகிறார்கள். அல்லாஹ் அவர்களிடமிருந்து நம்மைப் பாதுகாப்பானாக.<br />\r\n<br />\r\n<strong>மறுமை நாளில் நிராகரிப்பாளர்களிடமிருந்து எந்தச் சாக்குப்போக்கும் ஏற்கப்படாது</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُوا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَعْتَذِرُوا</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">تُجْزَوْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்களே! இன்றைய தினம் எந்தச் சாக்குப்போக்கையும் கூறாதீர்கள்! நீங்கள் செய்துகொண்டிருந்தவற்றுக்கு மட்டுமே இன்று உங்களுக்குக் கூலி வழங்கப்படுகிறது.) அதாவது, மறுமை நாளில் நிராகரிப்பாளர்களிடம், \"இன்று எந்தச் சாக்குப்போக்குகளையும் கூறாதீர்கள், ஏனெனில் அவை உங்களிடமிருந்து ஏற்றுக்கொள்ளப்பட மாட்டாது. நீங்கள் உலகில் என்ன செய்து கொண்டிருந்தீர்களோ, அதற்கான தண்டனையை மட்டுமே இன்று அனுபவிக்கிறீர்கள்\" என்று கூறப்படும்.<br />\r\n<br />\r\n<strong>உளப்பூர்வமான தவ்பாவை ஊக்குவித்தல்</strong><br />\r\n<br />\r\nஉயர்ந்தோன் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">تُوبُوا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">تَوْبَةً</span> <span class=\"quran-arabic-font text-success\">نَّصُوحًا</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களே! அல்லாஹ்விடம் மிகத் தூய்மையான முறையில் தவ்பா செய்து மீளுங்கள்!) அதாவது, ஒரு மனிதன் தான் செய்த முந்தைய பாவங்களை அழிக்கும் விதமாகவும், தனது குறைகளை நிவர்த்தி செய்யும் விதமாகவும், தான் செய்து வந்த தீமைகளை அறவே கைவிடும் விதமாகவும் அமையும் உண்மையான, உறுதியான தவ்பாவாகும். உமர் (ரழி) அவர்கள் கூறினார்கள்: \"தவ்பா நஸுஹா என்பது, கறந்த பால் மடுவில் திரும்பாதது போன்று, ஒருவன் பாவத்திலிருந்து விலகி மீண்டும் அதில் ஈடுபடாமல் இருப்பதாகும்.\" அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَسَى</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُكَفِّرَ</span> <span class=\"quran-arabic-font text-success\">عَنكُمْ</span> <span class=\"quran-arabic-font text-success\">سَيِّئَاتِكُمْ</span> <span class=\"quran-arabic-font text-success\">وَيُدْخِلَكُمْ</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">تَجْرِي</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ</span><br />\r\n<br />\r\n(உங்கள் இறைவன் உங்கள் பாவங்களை உங்களை விட்டும் போக்கி, ஆறுகள் ஓடும் சுவனச் சோலைகளில் உங்களை நுழையச் செய்யக்கூடும்.) அல்லாஹ் \"செய்யக்கூடும்\" (Asa) என்று கூறினால், அது \"நிச்சயமாகச் செய்வான்\" என்றே பொருள்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُخْزِي</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">النَّبِيَّ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">مَعَهُ</span><br />\r\n<br />\r\n(அந்நாளில் அல்லாஹ் நபியையும் (ஸல்), அவருடன் ஈமான் கொண்டவர்களையும் இழிவுபடுத்த மாட்டான்.) அதாவது, மறுமை நாளில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களை விசுவாசித்தவர்களை அல்லாஹ் ஒருபோதும் இழிவுபடுத்த மாட்டான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُورُهُمْ</span> <span class=\"quran-arabic-font text-success\">يَسْعَى</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَبِأَيْمَانِهِمْ</span><br />\r\n<br />\r\n(அவர்களின் ஒளி அவர்களுக்கு முன்னாலும், அவர்களின் வலது புறங்களிலும் விரைந்து செல்லும்.) இதை நாம் சூரத்துல் ஹதீதில் விளக்கியுள்ளோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">أَتْمِمْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">نُورَنَا</span> <span class=\"quran-arabic-font text-success\">وَاغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ</span><br />\r\n<br />\r\n(அவர்கள் கூறுவார்கள்: \"எங்கள் இறைவா! எங்களுக்காக எங்கள் ஒளியை முழுமையாக்குவாயாக; எங்களுக்கு மன்னிப்பு வழங்குவாயாக. நிச்சயமாக நீ அனைத்தின் மீதும் பேராற்றல் கொண்டவன்.\") முஜாஹித், அத்-தஹ்ஹாக், அல்-ஹஸன் அல்-பஸரி (ரழி) மற்றும் பிற அறிஞர்கள் கூறுகையில், \"மறுமை நாளில் நயவஞ்சகர்களின் ஒளி அணைக்கப்படுவதைக் காணும் போது, நம்பிக்கையாளர்கள் கூறும் பிரார்த்தனை இதுவாகும்\" என்கின்றனர். இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ள ஹதீஸில், பானு கினானா கோத்திரத்தைச் சேர்ந்த ஒருவர் கூறினார்: \"மக்கா வெற்றியின் போது நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்குப் பின்னால் நின்று தொழுதேன். அப்போது அவர்கள் பின்வருமாறு பிரார்த்திப்பதைக் கேட்டேன்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُخْزِنِي</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! மறுமை நாளில் என்னை இழிவுபடுத்திவிடாதே.)\"<br />\r\n<br />","text":"தன் குடும்பத்தாருக்கு மார்க்கத்தையும் நற்பண்புகளையும் கற்பித்தல்\n\r\n\n\r\nஅலி பின் அபி தல்ஹா (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்;\n\r\n\n\r\nقُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا\n\r\n\n\r\n(உங்களையும் உங்கள் குடும்பத்தினரையும் நரக நெருப்பிலிருந்து பாதுகாத்துக் கொள்ளுங்கள்) என்ற வசனத்திற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள், \"அல்லாஹ்வுக்குக் கீழ்ப்படிந்து நடங்கள், அல்லாஹ்வுக்கு மாறு செய்வதைத் தவிர்த்துக் கொள்ளுங்கள். உங்கள் குடும்பத்தினரை அல்லாஹ்வை நினைவு கூருமாறு ஏவுங்கள்; அப்போது அல்லாஹ் உங்களை நரக நெருப்பிலிருந்து காப்பாற்றுவான்\" என்று விளக்கமளித்தார்கள். முஜாஹித் (ரழி) அவர்களும்:\n\r\n\n\r\nقُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا\n\r\n\n\r\n(உங்களையும் உங்கள் குடும்பத்தினரையும் நரக நெருப்பிலிருந்து பாதுகாத்துக் கொள்ளுங்கள்) என்ற வசனத்திற்கு, \"அல்லாஹ்வை அஞ்சிக் கொள்ளுங்கள் (தக்வா), உங்கள் குடும்பத்தினரையும் அவனை அஞ்சுமாறு ஏவுங்கள்\" என்று விளக்கமளித்தார்கள். கதாதா (ரழி) அவர்கள் கூறும்போது, \"ஒருவர் அல்லாஹ்வுக்குக் கீழ்ப்படியுமாறு ஏவ வேண்டும், அவனுக்கு மாறு செய்வதைத் தவிர்க்க வேண்டும். தனது குடும்பத்தினரை அவனது கட்டளைகளுக்குப் பணியுமாறு ஏவி, அதன்படி செயல்பட அவர்களுக்கு உதவ வேண்டும். அவர்கள் ஏதேனும் மாறு செய்வதைக் கண்டால், அதைத் தடுத்து அவர்களை விலக்க வேண்டும்\" என்றார்கள். இதே போன்ற கருத்தை அத்-தஹ்ஹாக் மற்றும் முகாத்தில் (ரழி) அவர்களும் கூறியுள்ளனர்; \"அல்லாஹ் எவற்றை அவர்கள் மீது கடமையாக்கினானோ, எவற்றைத் தடை செய்துள்ளானோ, அவற்றை ஒரு முஸ்லிம் தனது நெருங்கிய உறவினர்களுக்கும், தனது ஆண் மற்றும் பெண் அடிமைகளுக்கும் கற்பிப்பது கடமையாகும்.\" இந்த வசனத்தின் பொருளை உறுதிப்படுத்தும் ஒரு ஹதீஸ் உள்ளது. அஹ்மத், அபூ தாவூத் மற்றும் அத்-திர்மிதி ஆகியோர் பதிவு செய்துள்ள ஹதீஸில், அர்-ரபீ பின் சப்ரா (ரழி) அவர்கள் தனது தந்தை கூறியதாக அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்,\n\r\n\n\r\n«مُرُوا الصَّبِيَّ بِالصَّلَاةِ إِذَا بَلَغَ سَبْعَ سِنِينَ، فَإِذَا بَلَغَ عَشْرَ سِنِينَ فَاضْرِبُوهُ عَلَيْهَا»\n\r\n\n\r\n(குழந்தைகள் ஏழு வயதை அடையும் போது அவர்களைத் தொழுமாறு ஏவுங்கள்; பத்து வயதை அடையும் போது (தொழுகையை நிறைவேற்றாவிட்டால்) அதற்காக அவர்களை அடியுங்கள்.) இது அபூ தாவூத் பதிவு செய்த அறிவிப்பாகும்; அத்-திர்மிதி இது \"ஹஸன்\" தரத்திலான ஹதீஸ் என்று குறிப்பிட்டுள்ளார்.\n\r\n\n\r\nநரகத்தின் எரிபொருளும் அதன் வானவர்களின் வர்ணனையும்\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nوَقُودُهَا النَّاسُ وَالْحِجَارَةُ\n\r\n\n\r\n(அதன் எரிபொருள் மனிதர்களும் கற்களுமாகும்,) ஆதமின் மக்கள் அந்த நரக நெருப்பை வளர்க்கும் எரிபொருளாக இருப்பார்கள் என்பதை இது குறிக்கிறது.\n\r\n\n\r\nوَالْحِجَارَةُ\n\r\n\n\r\n(மற்றும் கற்கள்) என்பது வணங்கப்பட்டு வந்த சிலைகளைக் குறிக்கிறது. இதை அல்லாஹ் மற்றொரு வசனத்தில் பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nإِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ اللَّهِ حَصَبُ جَهَنَّمَ\n\r\n\n\r\n(நிச்சயமாக நீங்களும், அல்லாஹ்வையன்றி நீங்கள் வணங்குபவையும் நரகத்தின் எரிபொருளே!) (21:98). அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி), முஜாஹித் (ரழி), அபூ ஜஃபர் அல்-பாகிர் (ரழி) மற்றும் அஸ்-சுத்தி (ரழி) ஆகியோர் இவை கந்தகக் கற்கள் என்று கூறுகின்றனர். இவை (வானத்தையும் பூமியையும் படைத்தபோதே அல்லாஹ் படைத்துவிட்ட) கந்தகக் கற்கள் என்றும், இவை அழுகிய பிணங்களை விடவும் அதிக துர்நாற்றம் வீசக்கூடியவை என்று முஜாஹித் (ரழி) குறிப்பிடுகிறார்கள். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nعَلَيْهَا مَلَائِكَةٌ غِلَاظٌ شِدَادٌ\n\r\n\n\r\n(அதன் மீது கடுமையானவர்களும் வலிமையானவர்களுமான வானவர்கள் (நியமிக்கப்பட்டு) இருக்கிறார்கள்,) அதாவது, அவர்களின் குணம் மிகவும் கடுமையானது; ஏனெனில் அல்லாஹ்வை நிராகரிப்பவர்கள் மீது இரக்கம் கொள்வது அவர்களின் இதயங்களிலிருந்து நீக்கப்பட்டுவிட்டது.\n\r\n\n\r\nشِدَادٌ\n\r\n\n\r\n(வலிமையானவர்கள்) அதாவது, அவர்களின் உடலமைப்பு மிகவும் ஆற்றல் மிக்கதும், அச்சமூட்டக்கூடியதும் ஆகும்.\n\r\n\n\r\nلَّا يَعْصُونَ اللَّهَ مَا أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ\n\r\n\n\r\n(அல்லாஹ் தங்களுக்கு இட்ட கட்டளைகளுக்கு அவர்கள் மாறு செய்வதில்லை; தங்களுக்குக் கட்டளையிடப்பட்டதையே அவர்கள் செய்கிறார்கள்.) அதாவது, அல்லாஹ் அவர்களுக்கு எதை ஏவினாலும், அவர்கள் ஒரு கண் இமைக்கும் நேரம்கூட தாமதிக்காமல் அவனுக்குக் கீழ்ப்படிய விரைந்து செல்வார்கள். அத்தகைய கட்டளைகளை நிறைவேற்றும் ஆற்றல் கொண்ட அவர்கள் 'அஸ்-ஸபானியா' (நரகத்தின் காவலர்கள்) என்று அழைக்கப்படுகிறார்கள். அல்லாஹ் அவர்களிடமிருந்து நம்மைப் பாதுகாப்பானாக.\n\r\n\n\r\nமறுமை நாளில் நிராகரிப்பாளர்களிடமிருந்து எந்தச் சாக்குப்போக்கும் ஏற்கப்படாது\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ كَفَرُوا لَا تَعْتَذِرُوا الْيَوْمَ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ\n\r\n\n\r\n(நிராகரிப்பாளர்களே! இன்றைய தினம் எந்தச் சாக்குப்போக்கையும் கூறாதீர்கள்! நீங்கள் செய்துகொண்டிருந்தவற்றுக்கு மட்டுமே இன்று உங்களுக்குக் கூலி வழங்கப்படுகிறது.) அதாவது, மறுமை நாளில் நிராகரிப்பாளர்களிடம், \"இன்று எந்தச் சாக்குப்போக்குகளையும் கூறாதீர்கள், ஏனெனில் அவை உங்களிடமிருந்து ஏற்றுக்கொள்ளப்பட மாட்டாது. நீங்கள் உலகில் என்ன செய்து கொண்டிருந்தீர்களோ, அதற்கான தண்டனையை மட்டுமே இன்று அனுபவிக்கிறீர்கள்\" என்று கூறப்படும்.\n\r\n\n\r\nஉளப்பூர்வமான தவ்பாவை ஊக்குவித்தல்\n\r\n\n\r\nஉயர்ந்தோன் அல்லாஹ் கூறினான்:\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَّصُوحًا\n\r\n\n\r\n(நம்பிக்கையாளர்களே! அல்லாஹ்விடம் மிகத் தூய்மையான முறையில் தவ்பா செய்து மீளுங்கள்!) அதாவது, ஒரு மனிதன் தான் செய்த முந்தைய பாவங்களை அழிக்கும் விதமாகவும், தனது குறைகளை நிவர்த்தி செய்யும் விதமாகவும், தான் செய்து வந்த தீமைகளை அறவே கைவிடும் விதமாகவும் அமையும் உண்மையான, உறுதியான தவ்பாவாகும். உமர் (ரழி) அவர்கள் கூறினார்கள்: \"தவ்பா நஸுஹா என்பது, கறந்த பால் மடுவில் திரும்பாதது போன்று, ஒருவன் பாவத்திலிருந்து விலகி மீண்டும் அதில் ஈடுபடாமல் இருப்பதாகும்.\" அல்லாஹ் கூறினான்:\n\r\n\n\r\nعَسَى رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّئَاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ\n\r\n\n\r\n(உங்கள் இறைவன் உங்கள் பாவங்களை உங்களை விட்டும் போக்கி, ஆறுகள் ஓடும் சுவனச் சோலைகளில் உங்களை நுழையச் செய்யக்கூடும்.) அல்லாஹ் \"செய்யக்கூடும்\" (Asa) என்று கூறினால், அது \"நிச்சயமாகச் செய்வான்\" என்றே பொருள்படும்.\n\r\n\n\r\nيَوْمَ لَا يُخْزِي اللَّهُ النَّبِيَّ وَالَّذِينَ آمَنُوا مَعَهُ\n\r\n\n\r\n(அந்நாளில் அல்லாஹ் நபியையும் (ஸல்), அவருடன் ஈமான் கொண்டவர்களையும் இழிவுபடுத்த மாட்டான்.) அதாவது, மறுமை நாளில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களை விசுவாசித்தவர்களை அல்லாஹ் ஒருபோதும் இழிவுபடுத்த மாட்டான்.\n\r\n\n\r\nنُورُهُمْ يَسْعَى بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ\n\r\n\n\r\n(அவர்களின் ஒளி அவர்களுக்கு முன்னாலும், அவர்களின் வலது புறங்களிலும் விரைந்து செல்லும்.) இதை நாம் சூரத்துல் ஹதீதில் விளக்கியுள்ளோம்.\n\r\n\n\r\nيَقُولُونَ رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ\n\r\n\n\r\n(அவர்கள் கூறுவார்கள்: \"எங்கள் இறைவா! எங்களுக்காக எங்கள் ஒளியை முழுமையாக்குவாயாக; எங்களுக்கு மன்னிப்பு வழங்குவாயாக. நிச்சயமாக நீ அனைத்தின் மீதும் பேராற்றல் கொண்டவன்.\") முஜாஹித், அத்-தஹ்ஹாக், அல்-ஹஸன் அல்-பஸரி (ரழி) மற்றும் பிற அறிஞர்கள் கூறுகையில், \"மறுமை நாளில் நயவஞ்சகர்களின் ஒளி அணைக்கப்படுவதைக் காணும் போது, நம்பிக்கையாளர்கள் கூறும் பிரார்த்தனை இதுவாகும்\" என்கின்றனர். இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ள ஹதீஸில், பானு கினானா கோத்திரத்தைச் சேர்ந்த ஒருவர் கூறினார்: \"மக்கா வெற்றியின் போது நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்குப் பின்னால் நின்று தொழுதேன். அப்போது அவர்கள் பின்வருமாறு பிரார்த்திப்பதைக் கேட்டேன்:\n\r\n\n\r\n«اللْهُمَّ لَا تُخْزِنِي يَوْمَ الْقِيَامَة»\n\r\n\n\r\n(யா அல்லாஹ்! மறுமை நாளில் என்னை இழிவுபடுத்திவிடாதே.)\""},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=66&ayah=10\" class=\"link\">66:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 66:10 ஐ பார்க்கவும்"},"10":{"html":"<strong>காஃபிர்கள் மற்றும் முனாஃபிக்குகளுக்கு எதிராக ஜிஹாத் செய்வதற்கான கட்டளை</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ், தனது தூதருக்கு (ஸல்) காஃபிர்கள் மற்றும் முனாஃபிக்குகளுக்கு எதிராக ஜிஹாத் செய்யுமாறு கட்டளையிடுகிறான். முந்தையவர்களுக்கு (காஃபிர்களுக்கு) எதிராக ஆயுதங்களைக் கொண்டும், பிந்தையவர்களுக்கு (முனாஃபிக்குகளுக்கு) எதிராக அல்லாஹ் விதித்துள்ள மார்க்க சட்ட வரம்புகளை (ஹதூத்) நிலைநாட்டுவதன் மூலமும் அல்லது ஆதாரங்களை எடுத்து வைப்பதன் மூலமும் ஜிஹாத் செய்யுமாறு ஏவுகிறான்.<span class=\"quran-arabic-font text-success\">﴾وَاغْلُظْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ﴿</span><br />\r\n<br />\r\n(அவர்களிடம் கடுமையாக நடந்து கொள்ளும்) அதாவது, இவ்வுலக வாழ்வில்.<span class=\"quran-arabic-font text-success\">﴾وَمَأْوَاهُمْ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمُ</span> <span class=\"quran-arabic-font text-success\">وَبِئْسَ</span> <span class=\"quran-arabic-font text-success\">الْمَصِيرُ﴿</span><br />\r\n<br />\r\n(அவர்களின் தங்குமிடம் நரகமாகும், அது சேருமிடங்களில் மிகவும் கெட்டது.) அதாவது, மறுமையில்.<br />\r\n<br />\r\n<strong>மறுமை நாளில் இறைமறுப்பாளர் தனது இறைநம்பிக்கை கொண்ட உறவினரால் எவ்விதப் பயனும் பெறமாட்டார்</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்,<span class=\"quran-arabic-font text-success\">﴾ضَرَبَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">لِّلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ﴿</span><br />\r\n<br />\r\n(நிராகரிப்பவர்களுக்கு அல்லாஹ் ஓர் உதாரணத்தைக் கூறுகிறான்) அதாவது, இவ்வுலகில் முஸ்லிம்களுடன் இணைந்து வாழும் இறைமறுப்பாளர்கள், முஸ்லிம்களுடன் கலந்து பழகுவது அவர்களுக்கு எவ்விதப் பயனும் அளிக்காது. அவர்கள் தங்கள் உள்ளங்களில் ஈமான் (இறைநம்பிக்கை) கொள்ளாத வரை அல்லாஹ்விடத்தில் அது அவர்களுக்கு உதவாது. பின்னர் அல்லாஹ் அந்த உவமையைக் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾امْرَأَتَ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span> <span class=\"quran-arabic-font text-success\">وَامْرَأَتَ</span> <span class=\"quran-arabic-font text-success\">لُوطٍ</span> <span class=\"quran-arabic-font text-success\">كَانَتَا</span> <span class=\"quran-arabic-font text-success\">تَحْتَ</span> <span class=\"quran-arabic-font text-success\">عَبْدَيْنِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِنَا</span> <span class=\"quran-arabic-font text-success\">صَالِحَيْنِ﴿</span><br />\r\n<br />\r\n(நூஹ்வுடைய மனைவியையும், லூத்துடைய மனைவியையும்; அவ்விருவரும் நம்முடைய அடியார்களில் ஸாலிஹான (நல்லொழுக்கமுள்ள) இரு அடியார்களின் கீழ் (மனைவியராக) இருந்தனர்,) அதாவது, அவர்கள் அல்லாஹ்வின் தூதர்களில் இருவரின் மனைவியராக இருந்தனர். ஒரு திருமண உறவில் கணவன்-மனைவிக்கு இடையே இருக்கும் நெருக்கத்தைப் போன்றே, அவர்கள் அந்தத் தூதர்களுடன் இரவும் பகலும் உடனிருந்து, அவர்களுடன் உண்டு உறங்கித் தோழமையுடன் வாழ்ந்தனர். இருப்பினும்,<span class=\"quran-arabic-font text-success\">﴾فَخَانَتَاهُمَا﴿</span><br />\r\n<br />\r\n(அவ்விருவரும் அவர்களுக்குத் துரோகம் செய்தனர்.) அதாவது, ஈமானின் (இறைநம்பிக்கையின்) விஷயத்தில் அவர்கள் தங்கள் கணவர்கள் மூலம் கொண்டு வரப்பட்ட மார்க்கத்தைப் பின்பற்றவில்லை; அவர்களது தூதுச்செய்தியை ஏற்கவும் இல்லை. எனவே, அவர்கள் தங்கள் கணவர்களைப் பற்றித் தெரிந்திருந்த நெருக்கமான விஷயங்கள் எதுவும் அவர்களுக்குப் பயன் அளிக்கவில்லை; இறைவனின் தண்டனையிலிருந்து அவர்களைப் பாதுகாக்கவும் இல்லை. அதனால்தான் அல்லாஹ்,<span class=\"quran-arabic-font text-success\">﴾فَلَمْ</span> <span class=\"quran-arabic-font text-success\">يُغْنِيَا</span> <span class=\"quran-arabic-font text-success\">عَنْهُمَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً﴿</span><br />\r\n<br />\r\n(ஆகவே, அல்லாஹ்விடமிருந்து (ஏற்படும் தண்டனையில்) எதனையும் அவர்கள் அவ்விருவருக்கும் தடுத்துவிட முடியவில்லை) என்று கூறுகிறான். அவர்களின் மனைவிகள் இறைமறுப்பாளர்களாக இருந்ததே இதற்குக் காரணம்.<span class=\"quran-arabic-font text-success\">﴾وَقِيلَ﴿</span><br />\r\n<br />\r\n(மேலும் கூறப்பட்டது) அதாவது, அந்த மனைவியரிடம்,<span class=\"quran-arabic-font text-success\">﴾ادْخُلاَ</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">الدَّاخِلِينَ﴿</span><br />\r\n<br />\r\n(நரகில் நுழைபவர்களுடன் சேர்ந்து நீங்களும் நுழையுங்கள்!) என்று கூறப்பட்டது. அந்த வசனத்தில் இடம்பெற்றுள்ள <span class=\"quran-arabic-font text-success\">﴾فَخَانَتَاهُمَا﴿</span><br />\r\n<br />\r\n(அவ்விருவரும் அவர்களுக்குத் துரோகம் செய்தனர்) என்பது சட்டவிரோத தாம்பத்திய உறவில் ஈடுபட்டதைக் குறிக்காது; மாறாக, மார்க்கத்தை ஏற்க மறுத்ததையே குறிக்கிறது. நிச்சயமாக, நபிமார்களுக்கு அல்லாஹ் வழங்கிய கண்ணியத்தின் காரணமாக, அவர்களுடைய மனைவிகள் இத்தகைய சட்டவிரோத தாம்பத்திய உறவில் ஈடுபடுவதிலிருந்து பாதுகாக்கப்பட்டவர்கள் என்பதை நாம் ஸூரத்துந் நூர் விளக்கவுரையில் விளக்கியுள்ளோம். அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அவர்கள் தங்கள் மார்க்கத்தைப் பின்பற்றாததன் மூலமே அவர்களுக்குத் துரோகம் செய்தனர். நூஹ் (அலை) அவர்களின் மனைவி, நூஹ் (அலை) அவர்களை ஏற்று எவரேனும் ஈமான் கொண்டால், அவர் ஒரு பைத்தியக்காரர் என்று கூறுவாள். மேலும் அந்த ரகசியத்தை அவருடைய அக்கிரமக்கார மக்களிடம் தெரிவித்துவிடுவார். லூத் (அலை) அவர்களின் மனைவியைப் பொறுத்தவரை, தன் கணவரிடம் (வானவர்கள்) விருந்தினராக வந்தபோது, அந்தத் தகவலை அருவருப்பான பாலியல் செயலில் (ஓரினச்சேர்க்கை) ஈடுபட்டிருந்த அந்த ஊர் (ஸதோம்) மக்களிடம் தெரிவித்துவிடுவார்.\" இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அத்-தஹ்ஹாக் (ரஹ்) அவர்கள் அறிவிக்கிறார்கள்: \"எந்தவொரு நபியின் மனைவியும் ஒருபோதும் விபச்சாரம் செய்ததில்லை. மாறாக, மார்க்கத்தைப் பின்பற்ற மறுத்ததன் மூலமே அவர்கள் துரோகம் செய்தனர்.\" இக்ரிமா (ரஹ்), ஸயீத் பின் ஜுபைர் (ரஹ்), அத்-தஹ்ஹாக் (ரஹ்) மற்றும் பிறரும் இதையே கூறியுள்ளனர்.<br />\r\n<br />","text":"காஃபிர்கள் மற்றும் முனாஃபிக்குகளுக்கு எதிராக ஜிஹாத் செய்வதற்கான கட்டளை\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ், தனது தூதருக்கு (ஸல்) காஃபிர்கள் மற்றும் முனாஃபிக்குகளுக்கு எதிராக ஜிஹாத் செய்யுமாறு கட்டளையிடுகிறான். முந்தையவர்களுக்கு (காஃபிர்களுக்கு) எதிராக ஆயுதங்களைக் கொண்டும், பிந்தையவர்களுக்கு (முனாஃபிக்குகளுக்கு) எதிராக அல்லாஹ் விதித்துள்ள மார்க்க சட்ட வரம்புகளை (ஹதூத்) நிலைநாட்டுவதன் மூலமும் அல்லது ஆதாரங்களை எடுத்து வைப்பதன் மூலமும் ஜிஹாத் செய்யுமாறு ஏவுகிறான்.﴾وَاغْلُظْ عَلَيْهِمْ﴿\n\r\n\n\r\n(அவர்களிடம் கடுமையாக நடந்து கொள்ளும்) அதாவது, இவ்வுலக வாழ்வில்.﴾وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ﴿\n\r\n\n\r\n(அவர்களின் தங்குமிடம் நரகமாகும், அது சேருமிடங்களில் மிகவும் கெட்டது.) அதாவது, மறுமையில்.\n\r\n\n\r\nமறுமை நாளில் இறைமறுப்பாளர் தனது இறைநம்பிக்கை கொண்ட உறவினரால் எவ்விதப் பயனும் பெறமாட்டார்\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்,﴾ضَرَبَ اللَّهُ مَثَلاً لِّلَّذِينَ كَفَرُواْ﴿\n\r\n\n\r\n(நிராகரிப்பவர்களுக்கு அல்லாஹ் ஓர் உதாரணத்தைக் கூறுகிறான்) அதாவது, இவ்வுலகில் முஸ்லிம்களுடன் இணைந்து வாழும் இறைமறுப்பாளர்கள், முஸ்லிம்களுடன் கலந்து பழகுவது அவர்களுக்கு எவ்விதப் பயனும் அளிக்காது. அவர்கள் தங்கள் உள்ளங்களில் ஈமான் (இறைநம்பிக்கை) கொள்ளாத வரை அல்லாஹ்விடத்தில் அது அவர்களுக்கு உதவாது. பின்னர் அல்லாஹ் அந்த உவமையைக் கூறுகிறான்:﴾امْرَأَتَ نُوحٍ وَامْرَأَتَ لُوطٍ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَالِحَيْنِ﴿\n\r\n\n\r\n(நூஹ்வுடைய மனைவியையும், லூத்துடைய மனைவியையும்; அவ்விருவரும் நம்முடைய அடியார்களில் ஸாலிஹான (நல்லொழுக்கமுள்ள) இரு அடியார்களின் கீழ் (மனைவியராக) இருந்தனர்,) அதாவது, அவர்கள் அல்லாஹ்வின் தூதர்களில் இருவரின் மனைவியராக இருந்தனர். ஒரு திருமண உறவில் கணவன்-மனைவிக்கு இடையே இருக்கும் நெருக்கத்தைப் போன்றே, அவர்கள் அந்தத் தூதர்களுடன் இரவும் பகலும் உடனிருந்து, அவர்களுடன் உண்டு உறங்கித் தோழமையுடன் வாழ்ந்தனர். இருப்பினும்,﴾فَخَانَتَاهُمَا﴿\n\r\n\n\r\n(அவ்விருவரும் அவர்களுக்குத் துரோகம் செய்தனர்.) அதாவது, ஈமானின் (இறைநம்பிக்கையின்) விஷயத்தில் அவர்கள் தங்கள் கணவர்கள் மூலம் கொண்டு வரப்பட்ட மார்க்கத்தைப் பின்பற்றவில்லை; அவர்களது தூதுச்செய்தியை ஏற்கவும் இல்லை. எனவே, அவர்கள் தங்கள் கணவர்களைப் பற்றித் தெரிந்திருந்த நெருக்கமான விஷயங்கள் எதுவும் அவர்களுக்குப் பயன் அளிக்கவில்லை; இறைவனின் தண்டனையிலிருந்து அவர்களைப் பாதுகாக்கவும் இல்லை. அதனால்தான் அல்லாஹ்,﴾فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ اللَّهِ شَيْئاً﴿\n\r\n\n\r\n(ஆகவே, அல்லாஹ்விடமிருந்து (ஏற்படும் தண்டனையில்) எதனையும் அவர்கள் அவ்விருவருக்கும் தடுத்துவிட முடியவில்லை) என்று கூறுகிறான். அவர்களின் மனைவிகள் இறைமறுப்பாளர்களாக இருந்ததே இதற்குக் காரணம்.﴾وَقِيلَ﴿\n\r\n\n\r\n(மேலும் கூறப்பட்டது) அதாவது, அந்த மனைவியரிடம்,﴾ادْخُلاَ النَّارَ مَعَ الدَّاخِلِينَ﴿\n\r\n\n\r\n(நரகில் நுழைபவர்களுடன் சேர்ந்து நீங்களும் நுழையுங்கள்!) என்று கூறப்பட்டது. அந்த வசனத்தில் இடம்பெற்றுள்ள ﴾فَخَانَتَاهُمَا﴿\n\r\n\n\r\n(அவ்விருவரும் அவர்களுக்குத் துரோகம் செய்தனர்) என்பது சட்டவிரோத தாம்பத்திய உறவில் ஈடுபட்டதைக் குறிக்காது; மாறாக, மார்க்கத்தை ஏற்க மறுத்ததையே குறிக்கிறது. நிச்சயமாக, நபிமார்களுக்கு அல்லாஹ் வழங்கிய கண்ணியத்தின் காரணமாக, அவர்களுடைய மனைவிகள் இத்தகைய சட்டவிரோத தாம்பத்திய உறவில் ஈடுபடுவதிலிருந்து பாதுகாக்கப்பட்டவர்கள் என்பதை நாம் ஸூரத்துந் நூர் விளக்கவுரையில் விளக்கியுள்ளோம். அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அவர்கள் தங்கள் மார்க்கத்தைப் பின்பற்றாததன் மூலமே அவர்களுக்குத் துரோகம் செய்தனர். நூஹ் (அலை) அவர்களின் மனைவி, நூஹ் (அலை) அவர்களை ஏற்று எவரேனும் ஈமான் கொண்டால், அவர் ஒரு பைத்தியக்காரர் என்று கூறுவாள். மேலும் அந்த ரகசியத்தை அவருடைய அக்கிரமக்கார மக்களிடம் தெரிவித்துவிடுவார். லூத் (அலை) அவர்களின் மனைவியைப் பொறுத்தவரை, தன் கணவரிடம் (வானவர்கள்) விருந்தினராக வந்தபோது, அந்தத் தகவலை அருவருப்பான பாலியல் செயலில் (ஓரினச்சேர்க்கை) ஈடுபட்டிருந்த அந்த ஊர் (ஸதோம்) மக்களிடம் தெரிவித்துவிடுவார்.\" இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அத்-தஹ்ஹாக் (ரஹ்) அவர்கள் அறிவிக்கிறார்கள்: \"எந்தவொரு நபியின் மனைவியும் ஒருபோதும் விபச்சாரம் செய்ததில்லை. மாறாக, மார்க்கத்தைப் பின்பற்ற மறுத்ததன் மூலமே அவர்கள் துரோகம் செய்தனர்.\" இக்ரிமா (ரஹ்), ஸயீத் பின் ஜுபைர் (ரஹ்), அத்-தஹ்ஹாக் (ரஹ்) மற்றும் பிறரும் இதையே கூறியுள்ளனர்."},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=66&ayah=12\" class=\"link\">66:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 66:12 ஐ பார்க்கவும்"},"12":{"html":"<strong>நிராகரிப்பாளர்களால் நம்பிக்கையாளர்களுக்கு எந்தத் தீங்கும் விளைவிக்க முடியாது</strong><br />\r\n<br />\r\nநம்பிக்கையாளர்கள் தேவைப்படும் பட்சத்தில் நிராகரிப்பாளர்களுடன் தொடர்பு கொள்வதால் அவர்களுக்கு எந்தத் தீங்கும் ஏற்படாது என்பதற்கு அல்லாஹ் கூறிய ஓர் உவமை இதுவாகும். கண்ணியமிக்க அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَتَّخِذِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرِينَ</span> <span class=\"quran-arabic-font text-success\">أَوْلِيَآءَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَفْعَلْ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">تُقَـةً</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்கள், மற்ற நம்பிக்கையாளர்களை விடுத்து நிராகரிப்பவர்களைப் பாதுகாவலர்களாக ஆக்கிக்கொள்ள வேண்டாம். எவர் அவ்வாறு செய்கிறாரோ, அவருக்கு அல்லாஹ்விடமிருந்து எந்த உதவியும் கிடைக்காது; அவர்களிடமிருந்து உங்களுக்கு ஏதேனும் ஆபத்து ஏற்படும் என்று நீங்கள் அஞ்சினாலன்றி.) (<a href=\"qurandisp.php?sura=3&ayah=28\" class=\"link\">3:28</a>) கதாதா (ரழி) கூறினார்கள்: \"பூமியில் உள்ளவர்களிலேயே ஃபிர்அவ்ன் மிகவும் கொடுங்கோலனாகவும், பெரும் நிராகரிப்பாளனாகவும் இருந்தான். அல்லாஹ்வின் மீது ஆணையாக! அவனது மனைவி தனது இறைவனுக்குக் கீழ்ப்படிந்து நடந்ததால், அவளது கணவனுடைய நிராகரிப்பு அவளைப் பாதிக்கவில்லை. எனவே, அல்லாஹ் நீதியான நீதிபதி என்பதையும், எவரையும் அவரவர் செய்த பாவங்களைத் தவிர வேறு எதற்காகவும் அவன் தண்டிக்க மாட்டான் என்பதையும் அறிந்து கொள்ளுங்கள்.\" இப்னு ஜரீர் அவர்கள் ஸுலைமான் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"ஃபிர்அவ்னின் மனைவி வெயிலில் வைத்து சித்திரவதை செய்யப்பட்டார். ஃபிர்அவ்ன் சித்திரவதையை முடிக்கும்போது, வானவர்கள் தங்கள் இறக்கைகளால் அவருக்கு நிழல் கொடுத்தனர். அவருக்குச் சொர்க்கத்திலுள்ள அவரது வீடு காட்டப்பட்டது.\" இப்னு ஜரீர் அவர்கள் அல்-காசிம் பின் அபி பஸ்ஸா கூறியதாகக் கூறுகிறார்கள்: \"ஃபிர்அவ்னின் மனைவி, 'யார் வெற்றி பெற்றார்?' என்று கேட்பது வழக்கம். 'மூஸா (அலை) அவர்களும் ஹாரூன் (அலை) அவர்களும் வெற்றி பெற்றார்கள்' என்று கூறப்பட்டபோது, 'மூஸா (அலை) மற்றும் ஹாரூன் (அலை) ஆகியோரின் இறைவனை நான் ஈமான் கொள்கிறேன்' என்று அவர் கூறினார். ஃபிர்அவ்ன் தனது ஆட்களை அவரிடம் அனுப்பி, 'மிகப் பெரிய கல் ஒன்றைக் கொண்டு வாருங்கள். அவர் தனது நம்பிக்கையில் உறுதியாக இருந்தால், அவர் மீது அந்தக் கல்லை எறியுங்கள்; இல்லையென்றால் அவர் எனது மனைவியாகவே இருக்கட்டும்' என்று கூறினான். அவர்கள் அவரிடம் வந்தபோது, அவர் வானத்தை அண்ணாந்து பார்த்தார். அப்போது சொர்க்கத்திலுள்ள தனது வீட்டை அவரால் காண முடிந்தது. அவர் தனது ஈமானில் (நம்பிக்கையில்) உறுதியாக இருந்தார். பின்னர் அவரது உயிர் கைப்பற்றப்பட்டது. அதன் பின்னரே உயிரற்ற அவரது உடலின் மீது அந்தக் கல் எறியப்பட்டது.\" இதுவே அவரது கூற்றின் பொருளாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">ابْنِ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">عِندَكَ</span> <span class=\"quran-arabic-font text-success\">بَيْتاً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">وَنَجِّنِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">وَعَمَلِهِ</span><br />\r\n<br />\r\n(என் இறைவனே! சொர்க்கத்தில் உன்னிடத்தில் எனக்கொரு வீட்டைக் கட்டுவாயாக. மேலும், ஃபிர்அவ்னிடமிருந்தும் அவனது செயல்களிலிருந்தும் என்னைக் காப்பாற்றுவாயாக) என்பதன் பொருள், 'அவனிடமிருந்து என்னைத் தப்புவிப்பாயாக; ஏனெனில் அவனது செயல்களில் எனக்கு எவ்விதப் பங்குமில்லை' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنَجِّنِى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْقَوْمِ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمِينَ</span><br />\r\n<br />\r\n(மேலும், அநீதி இழைக்கும் மக்களிடமிருந்தும் என்னைக் காப்பாற்றுவாயாக.) அவரது பெயர் ஆஸியா பின்த் முஸாஹிம் (ரழி) ஆகும். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">ابْنَةَ</span> <span class=\"quran-arabic-font text-success\">عِمْرَانَ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">أَحْصَنَتْ</span> <span class=\"quran-arabic-font text-success\">فَرْجَهَا</span><br />\r\n<br />\r\n(மேலும் இம்ரானின் மகள் மர்யம், அவர் தனது கற்பைப் பேணிக் காத்துக்கொண்டார்.) அதாவது, அவர் தனது கண்ணியத்தைப் பாதுகாத்து, ஒழுக்கக்கேடான விஷயங்களிலிருந்து விலகித் தூய்மையாக இருந்தார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَنَفَخْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رُّوحِنَا</span><br />\r\n<br />\r\n(மேலும் நாம் அவரிடம் நமது ரூஹிலிருந்து ஊதினோம்.) அதாவது, ஜிப்ரீல் (அலை) என்ற வானவர் மூலம். அல்லாஹ், ஜிப்ரீல் (அலை) அவர்களை மர்யம் (அலை) அவர்களிடம் அனுப்பினான். அவர் ஒரு முழுமையான மனித உருவில் அவர்களிடம் வந்தார். அவரது ஆடையின் ஒரு துவாரத்தின் வழியாக ஊதுமாறு அல்லாஹ் அவருக்குக் கட்டளையிட்டான். அந்த மூச்சு அவரது மர்ம உறுப்பின் வழியாகக் கருப்பைக்குள் சென்றது; இவ்வாறே ஈஸா (அலை) அவர்கள் உருவானார்கள். இதனால்தான் அல்லாஹ் இங்கே இவ்வாறு கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَنَفَخْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رُّوحِنَا</span> <span class=\"quran-arabic-font text-success\">وَصَدَّقَتْ</span> <span class=\"quran-arabic-font text-success\">بِكَلِمَـتِ</span> <span class=\"quran-arabic-font text-success\">رَبَّهَا</span> <span class=\"quran-arabic-font text-success\">وَكُتُبِهِ</span><br />\r\n<br />\r\n(மேலும் நாம் அவரிடம் நமது ரூஹிலிருந்து ஊதினோம். மேலும் அவர் தனது இறைவனின் வார்த்தைகளையும் அவனது வேதங்களையும் மெய்ப்பித்தார்,) அதாவது அவனது விதியையும் அவனது சட்டங்களையும் (உண்மையென ஏற்றார்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَانَتْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْقَـنِتِينَ</span><br />\r\n<br />\r\n(மேலும் அவர் கீழ்ப்படிந்து நடப்பவர்களில் ஒருவராக இருந்தார்.) இமாம் அஹ்மத் அவர்கள் இப்னு அப்பாஸ் (ரழி) கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தரையில் நான்கு கோடுகளை வரைந்துவிட்டு,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَتَدْرُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">هَذَا؟</span>»<br />\r\n<br />\r\n(இந்தக் கோடுகள் எதைக் குறிக்கின்றன என்று உங்களுக்குத் தெரியுமா?) என்று கேட்டார்கள். அதற்கு அவர்கள் (ஸஹாபாக்கள்), 'அல்லாஹ்வும் அவனது தூதருமே நன்கறிந்தவர்கள்' என்றனர். அப்போது அவர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَفْضَلُ</span> <span class=\"quran-arabic-font text-success\">نِسَاءِ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span>: <span class=\"quran-arabic-font text-success\">خَدِيجَةُ</span> <span class=\"quran-arabic-font text-success\">بِنْتُ</span> <span class=\"quran-arabic-font text-success\">خُوَيْلِدٍ،</span> <span class=\"quran-arabic-font text-success\">وَفَاطِمَةُ</span> <span class=\"quran-arabic-font text-success\">بِنْتُ</span> <span class=\"quran-arabic-font text-success\">مُحَمَّدٍ،</span> <span class=\"quran-arabic-font text-success\">وَمَرْيَمُ</span> <span class=\"quran-arabic-font text-success\">ابْنَةُ</span> <span class=\"quran-arabic-font text-success\">عِمْرَانَ،</span> <span class=\"quran-arabic-font text-success\">وَآسِيَةُ</span> <span class=\"quran-arabic-font text-success\">بِنْتُ</span> <span class=\"quran-arabic-font text-success\">مُزَاحِمٍ</span> <span class=\"quran-arabic-font text-success\">امْرَأَةُ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْن</span>»<br />\r\n<br />\r\n(சொர்க்கவாசிகளான பெண்களில் சிறந்தவர்கள்: குவைலிதின் மகள் கதீஜா (ரழி), முஹம்மதின் மகள் ஃபாத்திமா (ரழி), இம்ரானின் மகள் மர்யம் (அலை), ஃபிர்அவ்னின் மனைவி முஸாஹிமின் மகள் ஆஸியா (ரழி) ஆகியோராவர்.) அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்களிடமிருந்து புகாரீ, முஸ்லிம் ஆகிய இரு நூல்களிலும் (ஸஹீஹைன்) இவ்வாறாகப் பதிவு செய்யப்பட்டுள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كَمُلَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الرِّجَالِ</span> <span class=\"quran-arabic-font text-success\">كَثِيرٌ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكْمُلْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النِّسَاءِ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">آسِيَةُ</span> <span class=\"quran-arabic-font text-success\">امْرَأَةُ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ،</span> <span class=\"quran-arabic-font text-success\">وَمَرْيَمُ</span> <span class=\"quran-arabic-font text-success\">ابْنَةُ</span> <span class=\"quran-arabic-font text-success\">عِمْرَانَ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">فَضْلَ</span> <span class=\"quran-arabic-font text-success\">عَائِشَةَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النِّسَاءِ</span> <span class=\"quran-arabic-font text-success\">كَفَضْلِ</span> <span class=\"quran-arabic-font text-success\">الثَّرِيدِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">سَائِرِ</span> <span class=\"quran-arabic-font text-success\">الطَّعَام</span>»<br />\r\n<br />\r\n(ஆண்களில் பலர் முழுமை பெற்றுள்ளனர். ஆனால் பெண்களில் ஃபிர்அவ்னின் மனைவி ஆஸியா (ரழி), இம்ரானின் மகள் மர்யம் (அலை) ஆகியோரைத் தவிர வேறு யாரும் அந்த முழுமையை அடையவில்லை. மேலும், மற்ற பெண்களை விட ஆயிஷா (ரழி) அவர்களின் சிறப்பானது, மற்ற உணவுகளை விட 'தரீத்' எனும் உணவின் சிறப்பைப் போன்றதாகும்.) என்னுடைய 'அல்-பிதாயா வன்-நிஹாயா' எனும் நூலில், நபி ஈஸா (அலை) மற்றும் அவரது தாயார் மர்யம் (அலை) ஆகியோரின் வரலாற்றைக் குறிப்பிடும்போது, இந்த ஹதீஸ்களை அவற்றின் பல்வேறு அறிவிப்பாளர் தொடர்களுடன் விளக்கியுள்ளேன். அவர்கள் மீது இறைவனின் சாந்தி நிலவட்டும். எல்லாப் புகழும் அல்லாஹ்வுக்கே. இத்துடன் ஸூரத்துத் தஹ்ரீமின் தஃப்ஸீர் நிறைவு பெறுகிறது. அனைத்துப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />\r\n<br />\r\n<br />","text":"நிராகரிப்பாளர்களால் நம்பிக்கையாளர்களுக்கு எந்தத் தீங்கும் விளைவிக்க முடியாது\n\r\n\n\r\nநம்பிக்கையாளர்கள் தேவைப்படும் பட்சத்தில் நிராகரிப்பாளர்களுடன் தொடர்பு கொள்வதால் அவர்களுக்கு எந்தத் தீங்கும் ஏற்படாது என்பதற்கு அல்லாஹ் கூறிய ஓர் உவமை இதுவாகும். கண்ணியமிக்க அல்லாஹ் கூறினான்:\n\r\n\n\r\nلاَّ يَتَّخِذِ الْمُؤْمِنُونَ الْكَـفِرِينَ أَوْلِيَآءَ مِن دُونِ الْمُؤْمِنِينَ وَمَن يَفْعَلْ ذَلِكَ فَلَيْسَ مِنَ اللَّهِ فِي شَىْءٍ إِلاَ أَن تَتَّقُواْ مِنْهُمْ تُقَـةً\n\r\n\n\r\n(நம்பிக்கையாளர்கள், மற்ற நம்பிக்கையாளர்களை விடுத்து நிராகரிப்பவர்களைப் பாதுகாவலர்களாக ஆக்கிக்கொள்ள வேண்டாம். எவர் அவ்வாறு செய்கிறாரோ, அவருக்கு அல்லாஹ்விடமிருந்து எந்த உதவியும் கிடைக்காது; அவர்களிடமிருந்து உங்களுக்கு ஏதேனும் ஆபத்து ஏற்படும் என்று நீங்கள் அஞ்சினாலன்றி.) (3:28) கதாதா (ரழி) கூறினார்கள்: \"பூமியில் உள்ளவர்களிலேயே ஃபிர்அவ்ன் மிகவும் கொடுங்கோலனாகவும், பெரும் நிராகரிப்பாளனாகவும் இருந்தான். அல்லாஹ்வின் மீது ஆணையாக! அவனது மனைவி தனது இறைவனுக்குக் கீழ்ப்படிந்து நடந்ததால், அவளது கணவனுடைய நிராகரிப்பு அவளைப் பாதிக்கவில்லை. எனவே, அல்லாஹ் நீதியான நீதிபதி என்பதையும், எவரையும் அவரவர் செய்த பாவங்களைத் தவிர வேறு எதற்காகவும் அவன் தண்டிக்க மாட்டான் என்பதையும் அறிந்து கொள்ளுங்கள்.\" இப்னு ஜரீர் அவர்கள் ஸுலைமான் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"ஃபிர்அவ்னின் மனைவி வெயிலில் வைத்து சித்திரவதை செய்யப்பட்டார். ஃபிர்அவ்ன் சித்திரவதையை முடிக்கும்போது, வானவர்கள் தங்கள் இறக்கைகளால் அவருக்கு நிழல் கொடுத்தனர். அவருக்குச் சொர்க்கத்திலுள்ள அவரது வீடு காட்டப்பட்டது.\" இப்னு ஜரீர் அவர்கள் அல்-காசிம் பின் அபி பஸ்ஸா கூறியதாகக் கூறுகிறார்கள்: \"ஃபிர்அவ்னின் மனைவி, 'யார் வெற்றி பெற்றார்?' என்று கேட்பது வழக்கம். 'மூஸா (அலை) அவர்களும் ஹாரூன் (அலை) அவர்களும் வெற்றி பெற்றார்கள்' என்று கூறப்பட்டபோது, 'மூஸா (அலை) மற்றும் ஹாரூன் (அலை) ஆகியோரின் இறைவனை நான் ஈமான் கொள்கிறேன்' என்று அவர் கூறினார். ஃபிர்அவ்ன் தனது ஆட்களை அவரிடம் அனுப்பி, 'மிகப் பெரிய கல் ஒன்றைக் கொண்டு வாருங்கள். அவர் தனது நம்பிக்கையில் உறுதியாக இருந்தால், அவர் மீது அந்தக் கல்லை எறியுங்கள்; இல்லையென்றால் அவர் எனது மனைவியாகவே இருக்கட்டும்' என்று கூறினான். அவர்கள் அவரிடம் வந்தபோது, அவர் வானத்தை அண்ணாந்து பார்த்தார். அப்போது சொர்க்கத்திலுள்ள தனது வீட்டை அவரால் காண முடிந்தது. அவர் தனது ஈமானில் (நம்பிக்கையில்) உறுதியாக இருந்தார். பின்னர் அவரது உயிர் கைப்பற்றப்பட்டது. அதன் பின்னரே உயிரற்ற அவரது உடலின் மீது அந்தக் கல் எறியப்பட்டது.\" இதுவே அவரது கூற்றின் பொருளாகும்:\n\r\n\n\r\nرَبِّ ابْنِ لِى عِندَكَ بَيْتاً فِى الْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِ\n\r\n\n\r\n(என் இறைவனே! சொர்க்கத்தில் உன்னிடத்தில் எனக்கொரு வீட்டைக் கட்டுவாயாக. மேலும், ஃபிர்அவ்னிடமிருந்தும் அவனது செயல்களிலிருந்தும் என்னைக் காப்பாற்றுவாயாக) என்பதன் பொருள், 'அவனிடமிருந்து என்னைத் தப்புவிப்பாயாக; ஏனெனில் அவனது செயல்களில் எனக்கு எவ்விதப் பங்குமில்லை' என்பதாகும்.\n\r\n\n\r\nوَنَجِّنِى مِنَ الْقَوْمِ الظَّـلِمِينَ\n\r\n\n\r\n(மேலும், அநீதி இழைக்கும் மக்களிடமிருந்தும் என்னைக் காப்பாற்றுவாயாக.) அவரது பெயர் ஆஸியா பின்த் முஸாஹிம் (ரழி) ஆகும். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَمَرْيَمَ ابْنَةَ عِمْرَانَ الَّتِى أَحْصَنَتْ فَرْجَهَا\n\r\n\n\r\n(மேலும் இம்ரானின் மகள் மர்யம், அவர் தனது கற்பைப் பேணிக் காத்துக்கொண்டார்.) அதாவது, அவர் தனது கண்ணியத்தைப் பாதுகாத்து, ஒழுக்கக்கேடான விஷயங்களிலிருந்து விலகித் தூய்மையாக இருந்தார்.\n\r\n\n\r\nفَنَفَخْنَا فِيهِ مِن رُّوحِنَا\n\r\n\n\r\n(மேலும் நாம் அவரிடம் நமது ரூஹிலிருந்து ஊதினோம்.) அதாவது, ஜிப்ரீல் (அலை) என்ற வானவர் மூலம். அல்லாஹ், ஜிப்ரீல் (அலை) அவர்களை மர்யம் (அலை) அவர்களிடம் அனுப்பினான். அவர் ஒரு முழுமையான மனித உருவில் அவர்களிடம் வந்தார். அவரது ஆடையின் ஒரு துவாரத்தின் வழியாக ஊதுமாறு அல்லாஹ் அவருக்குக் கட்டளையிட்டான். அந்த மூச்சு அவரது மர்ம உறுப்பின் வழியாகக் கருப்பைக்குள் சென்றது; இவ்வாறே ஈஸா (அலை) அவர்கள் உருவானார்கள். இதனால்தான் அல்லாஹ் இங்கே இவ்வாறு கூறினான்:\n\r\n\n\r\nفَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَـتِ رَبَّهَا وَكُتُبِهِ\n\r\n\n\r\n(மேலும் நாம் அவரிடம் நமது ரூஹிலிருந்து ஊதினோம். மேலும் அவர் தனது இறைவனின் வார்த்தைகளையும் அவனது வேதங்களையும் மெய்ப்பித்தார்,) அதாவது அவனது விதியையும் அவனது சட்டங்களையும் (உண்மையென ஏற்றார்).\n\r\n\n\r\nوَكَانَتْ مِنَ الْقَـنِتِينَ\n\r\n\n\r\n(மேலும் அவர் கீழ்ப்படிந்து நடப்பவர்களில் ஒருவராக இருந்தார்.) இமாம் அஹ்மத் அவர்கள் இப்னு அப்பாஸ் (ரழி) கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தரையில் நான்கு கோடுகளை வரைந்துவிட்டு,\n\r\n\n\r\n«أَتَدْرُونَ مَا هَذَا؟»\n\r\n\n\r\n(இந்தக் கோடுகள் எதைக் குறிக்கின்றன என்று உங்களுக்குத் தெரியுமா?) என்று கேட்டார்கள். அதற்கு அவர்கள் (ஸஹாபாக்கள்), 'அல்லாஹ்வும் அவனது தூதருமே நன்கறிந்தவர்கள்' என்றனர். அப்போது அவர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَفْضَلُ نِسَاءِ أَهْلِ الْجَنَّةِ: خَدِيجَةُ بِنْتُ خُوَيْلِدٍ، وَفَاطِمَةُ بِنْتُ مُحَمَّدٍ، وَمَرْيَمُ ابْنَةُ عِمْرَانَ، وَآسِيَةُ بِنْتُ مُزَاحِمٍ امْرَأَةُ فِرْعَوْن»\n\r\n\n\r\n(சொர்க்கவாசிகளான பெண்களில் சிறந்தவர்கள்: குவைலிதின் மகள் கதீஜா (ரழி), முஹம்மதின் மகள் ஃபாத்திமா (ரழி), இம்ரானின் மகள் மர்யம் (அலை), ஃபிர்அவ்னின் மனைவி முஸாஹிமின் மகள் ஆஸியா (ரழி) ஆகியோராவர்.) அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்களிடமிருந்து புகாரீ, முஸ்லிம் ஆகிய இரு நூல்களிலும் (ஸஹீஹைன்) இவ்வாறாகப் பதிவு செய்யப்பட்டுள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«كَمُلَ مِنَ الرِّجَالِ كَثِيرٌ وَلَمْ يَكْمُلْ مِنَ النِّسَاءِ إِلَّا آسِيَةُ امْرَأَةُ فِرْعَوْنَ، وَمَرْيَمُ ابْنَةُ عِمْرَانَ، وَإِنَّ فَضْلَ عَائِشَةَ عَلَى النِّسَاءِ كَفَضْلِ الثَّرِيدِ عَلَى سَائِرِ الطَّعَام»\n\r\n\n\r\n(ஆண்களில் பலர் முழுமை பெற்றுள்ளனர். ஆனால் பெண்களில் ஃபிர்அவ்னின் மனைவி ஆஸியா (ரழி), இம்ரானின் மகள் மர்யம் (அலை) ஆகியோரைத் தவிர வேறு யாரும் அந்த முழுமையை அடையவில்லை. மேலும், மற்ற பெண்களை விட ஆயிஷா (ரழி) அவர்களின் சிறப்பானது, மற்ற உணவுகளை விட 'தரீத்' எனும் உணவின் சிறப்பைப் போன்றதாகும்.) என்னுடைய 'அல்-பிதாயா வன்-நிஹாயா' எனும் நூலில், நபி ஈஸா (அலை) மற்றும் அவரது தாயார் மர்யம் (அலை) ஆகியோரின் வரலாற்றைக் குறிப்பிடும்போது, இந்த ஹதீஸ்களை அவற்றின் பல்வேறு அறிவிப்பாளர் தொடர்களுடன் விளக்கியுள்ளேன். அவர்கள் மீது இறைவனின் சாந்தி நிலவட்டும். எல்லாப் புகழும் அல்லாஹ்வுக்கே. இத்துடன் ஸூரத்துத் தஹ்ரீமின் தஃப்ஸீர் நிறைவு பெறுகிறது. அனைத்துப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
